def _first_non_none(*values: object | None) -> object | None:
    for value in values:
        if value is not None:
            return value
    return None


def _first_present_value(*values: object | None) -> object | None:
    for value in values:
        if isinstance(value, str) and value.strip() in {"", "None"}:
            continue
        if value is not None:
            return value
    return None


