def _looks_like_diddesign_project_root(candidate: Path) -> bool:
    return all(
        (candidate / relative_path).exists()
        for relative_path in _PROJECT_ROOT_MARKER_PATHS
    )


def _candidate_project_roots(*starting_points: Path) -> Sequence[Path]:
    ordered_candidates: list[Path] = []
    seen: set[Path] = set()
    for starting_point in starting_points:
        for candidate in (starting_point, *starting_point.parents):
            resolved_candidate = candidate.resolve()
            if resolved_candidate in seen:
                continue
            seen.add(resolved_candidate)
            ordered_candidates.append(resolved_candidate)
    return tuple(ordered_candidates)


def _resolve_project_root(project_root: str | Path | None) -> Path:
    if project_root is not None:
        return Path(project_root).resolve()

    module_dir = Path(__file__).resolve().parent
    for candidate in _candidate_project_roots(Path.cwd().resolve(), module_dir):
        if _looks_like_diddesign_project_root(candidate):
            return candidate

    raise FileNotFoundError(
        "Could not auto-detect the diddesign project root; pass project_root explicitly."
    )


def _find_line_number_containing(path: Path, needle: str) -> int | None:
    try:
        lines = path.read_text(encoding="utf-8").splitlines()
    except OSError:
        return None
    for line_number, line in enumerate(lines, start=1):
        if needle in line:
            return line_number
    return None


def _format_line_number_spans(line_numbers: Sequence[int | None]) -> str | None:
    numeric_line_numbers = sorted(
        {line_number for line_number in line_numbers if line_number is not None}
    )
    if len(numeric_line_numbers) != len(line_numbers):
        return None
    if not numeric_line_numbers:
        return None
    spans: list[str] = []
    start = end = numeric_line_numbers[0]
    for line_number in numeric_line_numbers[1:]:
        if line_number == end + 1:
            end = line_number
            continue
        spans.append(f"{start}" if start == end else f"{start}-{end}")
        start = end = line_number
    spans.append(f"{start}" if start == end else f"{start}-{end}")
    return ",".join(spans)


def _appendix_g_anchor_line_ref(
    root: Path,
    relative_path: str,
    needles: Sequence[str],
) -> str | None:
    line_span = _format_line_number_spans(
        tuple(
            _find_line_number_containing(root / relative_path, needle)
            for needle in needles
        )
    )
    if line_span is None:
        return None
    return f"{relative_path}:{line_span}"


def _appendix_g_normalized_line_for_patterns(
    root: Path,
    *,
    relative_paths: Sequence[str],
    patterns: Sequence[str],
) -> str | None:
    for relative_path in relative_paths:
        candidate = root / relative_path
        if not candidate.exists():
            continue
        try:
            lines = candidate.read_text(encoding="utf-8").splitlines()
        except OSError:
            continue
        for line in lines:
            if any(pattern in line for pattern in patterns):
                normalized = line.strip()
                while normalized.startswith("- "):
                    normalized = normalized[2:].lstrip()
                return normalized
    return None


def _render_optional_yaml_folded_scalar_block(
    key: str,
    body: str,
    *,
    indent: int = 0,
) -> str | None:
    if not body.strip():
        return None
    return (
        replace_yaml_folded_scalar_block("", key, body, indent=indent)
        .lstrip()
        .rstrip("\n")
    )


def _appendix_g_automation_state_repo_compatibility_lines(
    project_root: str | Path,
) -> tuple[str, ...]:
    root = Path(project_root)
    lines: list[str] = []
    seen: set[str] = set()
    for patterns in _APPENDIX_G_AUTOMATION_STATE_COMPATIBILITY_LINE_PATTERNS:
        line = _appendix_g_normalized_line_for_patterns(
            root,
            relative_paths=_APPENDIX_G_AUTOMATION_STATE_COMPATIBILITY_SOURCE_RELATIVE_PATHS,
            patterns=patterns,
        )
        if line is None or line in seen:
            continue
        seen.add(line)
        lines.append(line)
    return tuple(lines)


