def _appendix_g_matching_read_only_confirmation_marker(
    snapshot: object,
    *,
    fallback: str | None = None,
) -> str | None:
    current_head_marker = getattr(snapshot, "current_head_marker", None)
    action_target_marker = getattr(snapshot, "phase_handoff_action_target_marker", None)
    phase_handoff_marker = getattr(
        snapshot, "phase_handoff_read_only_confirmation_marker", None
    )
    reopened_bounded_monitor_contract = (
        getattr(snapshot, "phase_handoff_recommended_action", None)
        == "bounded_monitor_existing_runner"
        and not bool(
            getattr(snapshot, "phase_handoff_second_bounded_monitor_forbidden", False)
        )
    )
    if bool(
        getattr(
            snapshot,
            "phase_handoff_current_head_outruns_bounded_monitor_floor",
            False,
        )
    ) or reopened_bounded_monitor_contract:
        return _first_non_none(
            current_head_marker,
            action_target_marker,
            fallback,
            phase_handoff_marker,
        )
    return _first_non_none(
        fallback,
        phase_handoff_marker,
        current_head_marker,
        action_target_marker,
    )


