class AutomationObservabilityStatus:
    """Machine-checkable summary for repo-side automation observability health."""

    run_log_path: str
    run_log_parse_error: str | None
    latest_finish_role: str | None
    latest_finish_timestamp: str | None
    canonical_roles_present: bool
    missing_canonical_roles: tuple[str, ...]
    workers_last_run_items: tuple[tuple[str, str], ...]
    last_writer_role: str | None
    last_writer_at: str | None
    last_writer_matches_latest_finish: bool
    latest_finish_role_last_run_at: str | None
    latest_finish_role_last_run_matches: bool
    expected_observability_name: str | None
    inbox_path: str | None
    inbox_present: bool
    run_report_path: str | None
    run_report_present: bool
    latest_shared_truth_timestamp: str | None
    documented_shared_truth_marker: str | None
    shared_truth_timestamp_outruns_latest_finish: bool
    latest_phase_summary_label: str | None
    latest_phase_plan_label: str | None
    finish_event_references_latest_inventory: bool
    finish_event_references_documented_shared_truth_marker: bool
    finish_event_references_progress_gap_metrics: bool
    finish_event_references_public_next_step: bool
    finish_event_references_full_blocker_bundle: bool
    finish_artifacts_reference_latest_inventory: bool
    finish_artifacts_reference_documented_shared_truth_marker: bool
    finish_artifacts_reference_progress_gap_metrics: bool
    finish_artifacts_reference_full_blocker_bundle: bool
    finish_artifacts_missing_full_blocker_bundle_keys: tuple[str, ...]
    finish_artifacts_missing_full_blocker_bundle_line_groups: tuple[
        tuple[str, tuple[str, ...]],
        ...,
    ]
    finish_artifacts_rerun_pending_segments: tuple[str, ...]
    duplicate_healthy_same_packet_finish_pairs: tuple[str, ...]
    current_goal_references_latest_inventory: bool
    current_goal_references_documented_shared_truth_marker: bool
    current_goal_references_progress_gap_metrics: bool
    open_constraints_references_latest_inventory: bool
    open_constraints_references_documented_shared_truth_marker: bool
    open_constraints_references_progress_gap_metrics: bool
    latest_finish_latest_phase_summary_label: str | None
    latest_finish_latest_phase_plan_label: str | None
    latest_finish_request_artifact_line: str | None
    latest_finish_run_mode_spec: str | None
    latest_finish_documented_shared_truth_marker: str | None
    latest_finish_phase_handoff_action_target_marker: str | None
    latest_finish_latest_finish_observability_healthy: str | None
    latest_finish_same_packet_reclaim_forbidden: str | None
    latest_finish_legal_next_step: str | None
    provisional_latest_finish_observability_healthy: bool | None
    provisional_same_packet_reclaim_forbidden: bool | None
    provisional_legal_next_step: str | None
    provisional_blocker_owner: str | None
    provisional_blocker_next_command_shell: str | None
    provisional_blocker_exit_criteria: str | None
    provisional_phase_handoff_action_target_marker: str | None
    provisional_phase_handoff_action_target_progress_successful_draw_count: int | None
    provisional_phase_handoff_action_target_remaining_successful_draw_count: int | None
    provisional_phase_handoff_progress_floor_lag: int | None
    provisional_phase_handoff_remaining_draw_lead: int | None
    provisional_request_artifact_line: str | None
    provisional_run_mode_spec: str | None
    provisional_phase_handoff_bounded_monitor_floor: str | None
    provisional_phase_handoff_read_only_confirmation_marker: str | None
    provisional_target_cell: str | None
    provisional_target_selection_source: str | None
    provisional_active_matching_runner_count: int | None
    provisional_active_matching_runner_pids: tuple[int, ...] | None
    provisional_launch_ready: bool | None
    provisional_routing_action: str | None
    provisional_current_outcome: str | None
    provisional_recovered_monitor_current_outcome: str | None
    provisional_target_progress_successful_draw_count: int | None
    provisional_target_remaining_successful_draw_count: int | None
    provisional_target_results_checkpoint_present: bool | None
    provisional_target_efficiency_checkpoint_present: bool | None
    provisional_target_missing_result_row_count: int | None
    provisional_target_efficiency_row_missing: bool | None
    provisional_follow_on_action: str | None
    provisional_blocker_class: str | None
    drift_reasons: tuple[str, ...]
    is_healthy: bool

    @property
    def status_reason(self) -> str:
        if self.is_healthy:
            return "healthy"
        if self.drift_reasons:
            return self.drift_reasons[0]
        return _AUTOMATION_OBSERVABILITY_PROVISIONAL_DRIFT_REASON

    @property
    def latest_finish_inbox_path(self) -> str | None:
        return self.inbox_path

    @property
    def latest_finish_run_report_path(self) -> str | None:
        return self.run_report_path

    @property
    def paired_inbox_path(self) -> str | None:
        return self.inbox_path

    @property
    def paired_run_report_path(self) -> str | None:
        return self.run_report_path

    @property
    def shared_truth_timestamp(self) -> str | None:
        return self.latest_shared_truth_timestamp

    @property
    def latest_finish_finish_time(self) -> str | None:
        return self.latest_finish_timestamp

    @property
    def last_writer(self) -> dict[str, str] | None:
        payload: dict[str, str] = {}
        if self.last_writer_role is not None:
            payload["role"] = self.last_writer_role
        if self.last_writer_at is not None:
            payload["at"] = self.last_writer_at
        return payload or None

    @property
    def workers_last_run(self) -> dict[str, str]:
        return dict(self.workers_last_run_items)

    @property
    def serializable_route_snapshot(self) -> dict[str, object]:
        snapshot: dict[str, object] = {
            "latest_finish_role": self.latest_finish_role,
            "latest_finish_timestamp": self.latest_finish_timestamp,
            "latest_finish_inbox_path": self.latest_finish_inbox_path,
            "latest_finish_run_report_path": self.latest_finish_run_report_path,
            "last_writer": self.last_writer,
            "workers_last_run": self.workers_last_run,
            "automation_observability_status_reason": self.status_reason,
            "automation_observability_drift_reasons": list(self.drift_reasons),
            "automation_observability_is_healthy": self.is_healthy,
            "shared_truth_timestamp_outruns_latest_finish": (
                self.shared_truth_timestamp_outruns_latest_finish
            ),
            "automation_observability_missing_full_blocker_bundle_keys": list(
                self.finish_artifacts_missing_full_blocker_bundle_keys
            ),
            "automation_observability_missing_full_blocker_bundle_line_groups": {
                key: list(lines)
                for key, lines in self.finish_artifacts_missing_full_blocker_bundle_line_groups
            },
            "finish_artifacts_rerun_pending_segments": list(
                self.finish_artifacts_rerun_pending_segments
            ),
            "duplicate_healthy_same_packet_finish_pairs": list(
                self.duplicate_healthy_same_packet_finish_pairs
            ),
        }
        optional_items = (
            ("latest_phase_summary_label", self.latest_phase_summary_label),
            ("latest_phase_plan_label", self.latest_phase_plan_label),
            ("documented_shared_truth_marker", self.documented_shared_truth_marker),
            (
                "latest_finish_documented_shared_truth_marker",
                self.latest_finish_documented_shared_truth_marker,
            ),
            (
                "latest_finish_phase_handoff_action_target_marker",
                self.latest_finish_phase_handoff_action_target_marker,
            ),
            (
                "phase_handoff_action_target_marker",
                self.phase_handoff_action_target_marker,
            ),
            (
                "phase_handoff_action_target_progress_successful_draw_count",
                self.phase_handoff_action_target_progress_successful_draw_count,
            ),
            (
                "phase_handoff_action_target_remaining_successful_draw_count",
                self.phase_handoff_action_target_remaining_successful_draw_count,
            ),
            ("request_artifact_line", self.request_artifact_line),
            ("run_mode_spec", self.run_mode_spec),
            (
                "phase_handoff_bounded_monitor_floor",
                self.phase_handoff_bounded_monitor_floor,
            ),
            (
                "phase_handoff_read_only_confirmation_marker",
                self.phase_handoff_read_only_confirmation_marker,
            ),
            ("target_cell", self.target_cell),
            ("target_selection_source", self.target_selection_source),
            (
                "active_matching_runner_count",
                self.active_matching_runner_count,
            ),
            ("launch_ready", self.launch_ready),
            ("routing_action", self.routing_action),
            ("current_outcome", self.current_outcome),
            (
                "recovered_monitor_current_outcome",
                self.recovered_monitor_current_outcome,
            ),
            (
                "phase_handoff_progress_floor_lag",
                self.phase_handoff_progress_floor_lag,
            ),
            (
                "phase_handoff_remaining_draw_lead",
                self.phase_handoff_remaining_draw_lead,
            ),
            ("current_progress_gap_metrics", self.current_progress_gap_metrics),
            (
                "target_progress_successful_draw_count",
                self.target_progress_successful_draw_count,
            ),
            (
                "target_remaining_successful_draw_count",
                self.target_remaining_successful_draw_count,
            ),
            (
                "target_results_checkpoint_present",
                self.target_results_checkpoint_present,
            ),
            (
                "target_efficiency_checkpoint_present",
                self.target_efficiency_checkpoint_present,
            ),
            (
                "target_missing_result_row_count",
                self.target_missing_result_row_count,
            ),
            (
                "target_efficiency_row_missing",
                self.target_efficiency_row_missing,
            ),
            ("follow_on_action", self.follow_on_action),
            ("blocker_class", self.blocker_class),
            (
                "latest_finish_observability_healthy",
                self.latest_finish_observability_healthy,
            ),
            (
                "same_packet_reclaim_forbidden",
                self.same_packet_reclaim_forbidden,
            ),
            ("legal_next_step", self.legal_next_step),
            ("recommended_action", self.recommended_action),
            ("owner", self.owner),
            ("next_command", self.next_command),
            ("exit_criteria", self.exit_criteria),
        )
        for key, value in optional_items:
            if value is not None:
                snapshot[key] = value
        if self.active_matching_runner_pids is not None:
            snapshot["active_matching_runner_pids"] = list(
                self.active_matching_runner_pids
            )
        return snapshot

