    def _prefer_phase_handoff_value(
        self,
        *phase_handoff_names: str,
        request_names: tuple[str, ...] | None = None,
    ) -> object | None:
        phase_handoff_status = self._current_phase_handoff_status
        if phase_handoff_status is not None:
            explicit_value = _appendix_g_explicit_status_attr(
                phase_handoff_status, *phase_handoff_names
            )
            if explicit_value is not None:
                return explicit_value
            for name in phase_handoff_names:
                value = getattr(phase_handoff_status, name, None)
                if value is not None:
                    return value

        lookup_names = request_names or phase_handoff_names
        explicit_request_value = _appendix_g_explicit_status_attr(
            self._current_execution_request, *lookup_names
        )
        if explicit_request_value is not None:
            return explicit_request_value
        for name in lookup_names:
            value = getattr(self._current_execution_request, name, None)
            if value is not None:
                return value
        return None

