    @cached_property
    def _latest_finish_closeout_paths(self) -> tuple[str | None, str | None]:
        root = Path(self.project_root)
        finish_event, run_log_parse_error = _latest_run_log_finish_event_for_root(root)
        if run_log_parse_error is not None or not isinstance(finish_event, dict):
            return (None, None)

        def _normalize_path(value: object | None) -> str | None:
            if value is None:
                return None
            normalized = str(value).strip()
            return normalized or None

        inbox_path = _first_non_none(
            _normalize_path(finish_event.get("latest_finish_inbox_path")),
            _normalize_path(finish_event.get("paired_inbox")),
            _normalize_path(finish_event.get("inbox_path")),
        )
        run_report_path = _first_non_none(
            _normalize_path(finish_event.get("latest_finish_run_report_path")),
            _normalize_path(finish_event.get("paired_run_report")),
            _normalize_path(finish_event.get("run_report_path")),
        )
        if inbox_path is None or run_report_path is None:
            finish_role = finish_event.get("role")
            finish_timestamp = finish_event.get("timestamp")
            if isinstance(finish_role, str) and isinstance(finish_timestamp, str):
                try:
                    finish_datetime = datetime.strptime(
                        finish_timestamp,
                        "%Y-%m-%dT%H:%M:%S%z",
                    )
                except ValueError:
                    finish_datetime = None
                if finish_datetime is not None:
                    observability_name = (
                        f"{finish_datetime.strftime('%Y%m%d-%H%M')}-{finish_role}.md"
                    )
                    automation_root = root / "_bmad-output" / "automation"
                    if inbox_path is None:
                        inbox_path = (
                            automation_root / "inbox" / observability_name
                        ).as_posix()
                    if run_report_path is None:
                        run_report_path = (
                            automation_root / "run-reports" / observability_name
                        ).as_posix()
        return (_normalize_path(inbox_path), _normalize_path(run_report_path))

