    latest_observed_log_tail: str | None = None
    latest_observed_log_tail_successful_draw_count: int | None = None
    latest_observed_log_tail_attempt_index: int | None = None

    @property
    def bridge_ready(self) -> bool:
        return self.source_bridge_ready

    @property
    def bridge_source_bridge_ready(self) -> bool:
        return self.source_bridge_ready

    @property
    def log_directory_path(self) -> str:
        return Path(self.missing_cells_log_path).parent.as_posix()

    @property
    def export_directory_path(self) -> str:
        return Path(self.aggregate_result_export_path).parent.as_posix()

    @property
    def logs_share_export_directory(self) -> bool:
        return self.log_directory_path == self.export_directory_path

    @property
    def relaunch_forbidden(self) -> bool:
        return self.source_bridge_ready and self.stale_missing_cells_log_is_nonblocking

    @property
    def resume_gate_preserved(self) -> bool:
        return (
            self.request_artifact_matches_target
            and self.run_mode_spec is not None
            and self.run_mode_spec.startswith(
                "resume_appendix_g_full_simulation_lane_missing_cells__"
            )
            and self.target_progress_checkpoint_present
            and not self.target_results_checkpoint_present
            and not self.target_efficiency_checkpoint_present
        )

    @property
    def targeted_resume_expected_chunk_size(self) -> int | None:
        if self.run_mode_spec is None:
            return None
        if self.run_mode_spec.startswith(
            (
                "resume_appendix_g_full_simulation_lane_missing_cells__",
                "run_appendix_g_full_simulation_lane_missing_cells__",
            )
        ):
            return 1
        return None

    @property
    def target_progress_checkpoint_chunk_size_matches_targeted_resume(self) -> bool:
        expected_chunk_size = self.targeted_resume_expected_chunk_size
        return (
            expected_chunk_size is not None
            and self.target_progress_checkpoint_chunk_size is not None
            and self.target_progress_checkpoint_chunk_size == expected_chunk_size
        )

    @property
    def target_progress_checkpoint_chunk_size_drifted(self) -> bool:
        expected_chunk_size = self.targeted_resume_expected_chunk_size
        return (
            expected_chunk_size is not None
            and self.target_progress_checkpoint_chunk_size is not None
            and self.target_progress_checkpoint_chunk_size != expected_chunk_size
        )

    @property
    def current_outcome(self) -> str:
        if (
            not self.source_bridge_ready
            and self.blocker_class == "runtime_probe_source_path_missing"
        ):
            return "runtime_probe_source_path_missing"
        if (
            self.target_results_checkpoint_present
            and self.target_efficiency_checkpoint_present
        ):
            return "materialization_complete"
        if self.active_matching_runner_count > 0:
            if (
                self.target_progress_checkpoint_present
                and self.target_progress_successful_draw_count is not None
                and not self.target_results_checkpoint_present
                and not self.target_efficiency_checkpoint_present
            ):
                return "runner_alive_with_progress_checkpoint"
            return "runner_alive_no_progress"
        if self.launch_ready and self.active_matching_runner_count == 0:
            return "launch_targeted_rerun"
        return self.routing_action

    @property
    def bridge_current_outcome(self) -> str:
        return self.current_outcome

    @property
    def controlled_stop_contract_ready(self) -> bool:
        return (
            self.same_pid_stale_runner_suspected
            and self.controlled_stop_decision_plan_present
            and self.source_bridge_ready
            and self.relaunch_forbidden
            and self.active_matching_runner_count > 0
            and not self.launch_ready
            and self.resume_gate_preserved
        )

    @property
    def controlled_stop_decision_outcome(self) -> str:
        if (
            self.target_results_checkpoint_present
            and self.target_efficiency_checkpoint_present
        ):
            return "cell_completed"
        if self.controlled_stop_contract_ready:
            return "controlled_stop_contract_ready"
        if (
            self.active_matching_runner_count == 0
            and not self.launch_ready
            and self.resume_gate_preserved
        ):
            return "pid_exited_resume_ready_without_stop"
        if (
            self.active_matching_runner_count > 0
            and self.resume_gate_preserved
            and not self.same_pid_stale_runner_suspected
        ):
            return "runner_recovered_before_stop"
        return self.current_outcome

    @property
    def controlled_stop_recommended_action(self) -> str:
        outcome = self.controlled_stop_decision_outcome
        if outcome == "cell_completed":
            return "materialization_complete"
        if outcome == "controlled_stop_contract_ready":
            return "controlled_stop_then_fresh_reprobe"
        if outcome == "pid_exited_resume_ready_without_stop":
            return "resume_existing_checkpoint"
        if outcome == "runner_recovered_before_stop":
            return "monitor_existing_runner"
        return self.recommended_action

    @property
    def bridge_target_progress_successful_draw_count(self) -> int | None:
        return self.target_progress_successful_draw_count

    @property
    def recommended_action(self) -> str:
        if not self.source_bridge_ready and self.legal_next_step is not None:
            return self.legal_next_step
        if (
            self.target_results_checkpoint_present
            and self.target_efficiency_checkpoint_present
        ):
            return "materialization_complete"
        if self.controlled_stop_contract_ready:
            return "controlled_stop_then_fresh_reprobe"
        if self.relaunch_forbidden:
            return "monitor_existing_runner"
        if self.launch_ready and self.active_matching_runner_count == 0:
            return "launch_targeted_rerun"
        return self.routing_action

    @property
    def bridge_recommended_action(self) -> str:
        return self.recommended_action

    @property
    def serializable_route_snapshot(self) -> dict[str, object]:
        snapshot: dict[str, object] = {
            name: list(value) if isinstance(value, tuple) else value
            for name, value in self.__dict__.items()
        }
        snapshot.update(
            {
                "bridge_ready": self.bridge_ready,
                "bridge_source_bridge_ready": self.bridge_source_bridge_ready,
                "bridge_current_outcome": self.bridge_current_outcome,
                "bridge_recommended_action": self.bridge_recommended_action,
                "bridge_target_progress_successful_draw_count": (
                    self.bridge_target_progress_successful_draw_count
                ),
                "log_directory_path": self.log_directory_path,
                "export_directory_path": self.export_directory_path,
                "logs_share_export_directory": self.logs_share_export_directory,
                "relaunch_forbidden": self.relaunch_forbidden,
                "resume_gate_preserved": self.resume_gate_preserved,
                "targeted_resume_expected_chunk_size": (
                    self.targeted_resume_expected_chunk_size
                ),
                "target_progress_checkpoint_chunk_size_matches_targeted_resume": (
                    self.target_progress_checkpoint_chunk_size_matches_targeted_resume
                ),
                "target_progress_checkpoint_chunk_size_drifted": (
                    self.target_progress_checkpoint_chunk_size_drifted
                ),
                "current_outcome": self.current_outcome,
                "controlled_stop_contract_ready": self.controlled_stop_contract_ready,
                "controlled_stop_decision_outcome": (
                    self.controlled_stop_decision_outcome
                ),
                "controlled_stop_recommended_action": (
                    self.controlled_stop_recommended_action
                ),
                "recommended_action": self.recommended_action,
            }
        )
        return snapshot


