@dataclass(frozen=True)
class AppendixGFullSimulationLaneTargetedRerunRelockStatus:
    """Outcome for one exact targeted rerun plus shared-truth relock when the route stays healthy."""

    execution_status: AppendixGFullSimulationLaneTargetedRerunExecutionStatus
    shared_truth_relocked: bool
    updated_paths: tuple[str, ...]
    relocked_oracle_status: object | None
    relocked_latest_finish_observability_packet: str | None
    relocked_latest_finish_closeout_packet_bundle: str | None

    @property
    def serializable_route_snapshot(self) -> dict[str, object]:
        snapshot: dict[str, object] = {
            "execution_outcome": self.execution_status.outcome,
            "recommended_action": self.execution_status.recommended_action,
            "shared_truth_relocked": self.shared_truth_relocked,
            "updated_paths": list(self.updated_paths),
        }
        if self.relocked_latest_finish_observability_packet:
            snapshot["relocked_latest_finish_observability_packet"] = (
                self.relocked_latest_finish_observability_packet
            )
        if self.relocked_latest_finish_closeout_packet_bundle:
            snapshot["relocked_latest_finish_closeout_packet_bundle"] = (
                self.relocked_latest_finish_closeout_packet_bundle
            )
        oracle_snapshot = getattr(
            self.relocked_oracle_status, "serializable_route_snapshot", None
        )
        if isinstance(oracle_snapshot, dict):
            snapshot.update(oracle_snapshot)
            return snapshot
        for name in (
            "request_artifact_line",
            "run_mode_spec",
            "phase_handoff_read_only_confirmation_marker",
        ):
            value = getattr(self.relocked_oracle_status, name, None)
            if value is not None:
                snapshot[name] = value
        return snapshot


@dataclass(frozen=True)
class AppendixGFullSimulationLaneSharedTruthRepairStatus:
    """Outcome for one shared-truth repair pass before any later bounded monitor."""

    repair_action: str
    shared_truth_relocked: bool
    updated_paths: tuple[str, ...]
    relocked_oracle_status: object | None
    relocked_automation_observability_status: object | None
    relocked_latest_finish_observability_packet: str | None
    relocked_latest_finish_closeout_packet_bundle: str | None
    request_artifact_alignment_status: object | None = None

    @staticmethod
    def _coalesce(*values: object | None) -> object | None:
        for value in values:
            if value is not None:
                return value
        return None

    @property
    def public_next_step(self) -> str | None:
        return getattr(self.relocked_oracle_status, "public_next_step", None)

    @property
    def owner(self) -> str | None:
        return getattr(self.relocked_oracle_status, "owner", None)

    @property
    def next_command(self) -> str | None:
        return getattr(self.relocked_oracle_status, "next_command", None)

    @property
    def exit_criteria(self) -> str | None:
        return getattr(self.relocked_oracle_status, "exit_criteria", None)

    @property
    def latest_finish_observability_healthy(self) -> bool | None:
        return getattr(
            self.relocked_oracle_status,
            "latest_finish_observability_healthy",
            None,
        )

    @property
    def same_packet_reclaim_forbidden(self) -> bool | None:
        return getattr(
            self.relocked_oracle_status,
            "same_packet_reclaim_forbidden",
            None,
        )

    @property
    def legal_next_step(self) -> str | None:
        return getattr(self.relocked_oracle_status, "legal_next_step", None)

    @property
    def latest_finish_inbox_path(self) -> str | None:
        value = self._coalesce(
            getattr(
                self.relocked_automation_observability_status,
                "latest_finish_inbox_path",
                None,
            ),
            getattr(
                self.relocked_automation_observability_status,
                "paired_inbox_path",
                None,
            ),
            getattr(self.relocked_automation_observability_status, "inbox_path", None),
        )
        return value if isinstance(value, str) else None

    @property
    def latest_finish_run_report_path(self) -> str | None:
        value = self._coalesce(
            getattr(
                self.relocked_automation_observability_status,
                "latest_finish_run_report_path",
                None,
            ),
            getattr(
                self.relocked_automation_observability_status,
                "paired_run_report_path",
                None,
            ),
            getattr(
                self.relocked_automation_observability_status,
                "run_report_path",
                None,
            ),
        )
        return value if isinstance(value, str) else None

    @property
    def serializable_route_snapshot(self) -> dict[str, object]:
        snapshot: dict[str, object] = {
            "repair_action": self.repair_action,
            "shared_truth_relocked": self.shared_truth_relocked,
            "updated_paths": list(self.updated_paths),
        }
        alignment_snapshot = getattr(
            self.request_artifact_alignment_status,
            "serializable_route_snapshot",
            None,
        )
        if isinstance(alignment_snapshot, dict):
            snapshot["request_artifact_alignment_action"] = alignment_snapshot.get(
                "alignment_action"
            )
            snapshot["request_artifact_alignment_reason"] = alignment_snapshot.get(
                "alignment_reason"
            )
            snapshot["request_artifact_alignment_attempted"] = alignment_snapshot.get(
                "alignment_attempted"
            )
            snapshot["request_artifact_updated"] = alignment_snapshot.get(
                "request_artifact_updated"
            )
            snapshot["request_artifact_alignment_updated_paths"] = (
                alignment_snapshot.get("updated_paths", [])
            )
            snapshot["previous_request_artifact_line"] = alignment_snapshot.get(
                "previous_request_artifact_line"
            )
            snapshot["post_alignment_request_artifact_line"] = alignment_snapshot.get(
                "request_artifact_line"
            )
            snapshot["pre_alignment_target_selection_source"] = alignment_snapshot.get(
                "target_selection_source"
            )
            snapshot["post_alignment_target_selection_source"] = alignment_snapshot.get(
                "post_alignment_target_selection_source"
            )
        if self.relocked_latest_finish_observability_packet:
            snapshot["relocked_latest_finish_observability_packet"] = (
                self.relocked_latest_finish_observability_packet
            )
        if self.relocked_latest_finish_closeout_packet_bundle:
            snapshot["relocked_latest_finish_closeout_packet_bundle"] = (
                self.relocked_latest_finish_closeout_packet_bundle
            )
        latest_finish_inbox_path = self.latest_finish_inbox_path
        latest_finish_run_report_path = self.latest_finish_run_report_path
        drift_reasons = getattr(
            self.relocked_automation_observability_status,
            "drift_reasons",
            None,
        )
        if latest_finish_inbox_path is not None:
            snapshot["latest_finish_inbox_path"] = latest_finish_inbox_path
        if latest_finish_run_report_path is not None:
            snapshot["latest_finish_run_report_path"] = latest_finish_run_report_path
        for snapshot_key, attr_name in (
            ("latest_finish_role", "latest_finish_role"),
            ("latest_finish_timestamp", "latest_finish_timestamp"),
            ("last_writer_role", "last_writer_role"),
            ("last_writer_at", "last_writer_at"),
            (
                "shared_truth_timestamp_outruns_latest_finish",
                "shared_truth_timestamp_outruns_latest_finish",
            ),
        ):
            value = getattr(self.relocked_automation_observability_status, attr_name, None)
            if value is not None:
                snapshot[snapshot_key] = value
        is_healthy = getattr(
            self.relocked_automation_observability_status,
            "is_healthy",
            None,
        )
        if is_healthy is not None:
            snapshot["automation_observability_is_healthy"] = bool(is_healthy)
        status_reason = getattr(
            self.relocked_automation_observability_status,
            "status_reason",
            None,
        )
        if status_reason is not None:
            snapshot["automation_observability_status_reason"] = status_reason
        if drift_reasons is not None:
            snapshot["automation_observability_drift_reasons"] = list(drift_reasons)
        missing_full_blocker_bundle_keys = getattr(
            self.relocked_automation_observability_status,
            "finish_artifacts_missing_full_blocker_bundle_keys",
            None,
        )
        if missing_full_blocker_bundle_keys is not None:
            snapshot["automation_observability_missing_full_blocker_bundle_keys"] = (
                list(missing_full_blocker_bundle_keys)
            )
        missing_full_blocker_bundle_line_groups = getattr(
            self.relocked_automation_observability_status,
            "finish_artifacts_missing_full_blocker_bundle_line_groups",
            None,
        )
        if missing_full_blocker_bundle_line_groups is not None:
            snapshot["automation_observability_missing_full_blocker_bundle_line_groups"] = {
                key: list(line_group)
                for key, line_group in missing_full_blocker_bundle_line_groups
            }
        oracle_snapshot = getattr(
            self.relocked_oracle_status, "serializable_route_snapshot", None
        )
        if isinstance(oracle_snapshot, dict):
            snapshot.update(oracle_snapshot)
            for name in (
                "observed_request_artifact_line",
                "effective_request_artifact_line",
                "request_artifact_stale_for_effective_target",
                "request_artifact_relation_to_effective_target",
                "target_request_line",
            ):
                if name not in snapshot:
                    value = getattr(self.relocked_oracle_status, name, None)
                    if value is not None:
                        snapshot[name] = value
            return snapshot
        for name in (
            "request_artifact_line",
            "observed_request_artifact_line",
            "effective_request_artifact_line",
            "request_artifact_stale_for_effective_target",
            "request_artifact_relation_to_effective_target",
            "target_request_line",
            "run_mode_spec",
            "phase_handoff_read_only_confirmation_marker",
            "phase_handoff_action_target_marker",
        ):
            value = getattr(self.relocked_oracle_status, name, None)
            if value is not None:
                snapshot[name] = value
        return snapshot


