@dataclass(frozen=True)
class AppendixGFullSimulationLaneRunnerRecoveredMonitorStatus:
    """Machine-checkable status for the recovered-runner bounded monitor contract."""

    current_frontier: str
    next_rung: str
    runner_recovered_monitor_plan_path: str
    runner_recovered_monitor_plan_present: bool
    request_artifact_line: str | None
    request_artifact_matches_target: bool
    run_mode_spec: str | None
    active_matching_runner_pids: tuple[int, ...]
    active_matching_runner_count: int
    launch_ready: bool
    target_progress_checkpoint_present: bool
    target_progress_checkpoint_chunk_size: int | None
    target_progress_successful_draw_count: int | None
    target_progress_attempt_index: int | None
    target_results_checkpoint_present: bool
    target_efficiency_checkpoint_present: bool
    stale_missing_cells_log_is_nonblocking: bool
    same_pid_stale_runner_suspected: bool
    controlled_stop_contract_ready: bool
    controlled_stop_decision_outcome: str
    controlled_stop_recommended_action: str
    live_target_progress_checkpoint_mtime_marker: str | None = None
    live_target_current_head_marker: str | None = None
    latest_observed_log_tail: str | None = None
    latest_observed_log_tail_successful_draw_count: int | None = None
    latest_observed_log_tail_attempt_index: int | None = None
    active_matching_runner_elapsed_seconds: tuple[int | None, ...] = ()
    same_target_multi_runner_conflict: bool = False
    oldest_active_matching_runner_pid: int | None = None
    newest_active_matching_runner_pid: int | None = None
    phase_handoff_target_progress_successful_draw_count: int | None = None
    phase_handoff_target_remaining_successful_draw_count: int | None = None
    phase_handoff_bounded_monitor_floor: str | None = None
    phase_handoff_read_only_confirmation_marker: str | None = None
    phase_handoff_progress_floor_lag: int | None = None
    phase_handoff_remaining_draw_lead: int | None = None
    phase_handoff_live_request_drifted: bool = False
    phase_handoff_recommended_action: str | None = None
    phase_handoff_progress_floor_is_conservative: bool = False
    phase_handoff_second_bounded_monitor_forbidden: bool = False
    phase_handoff_current_head_outruns_bounded_monitor_floor: bool = False

    @property
    def phase_handoff_action_target_marker(self) -> str | None:
        return (
            self.live_target_current_head_marker
            or self.phase_handoff_read_only_confirmation_marker
        )

    @property
    def targeted_resume_expected_chunk_size(self) -> int | None:
        if self.run_mode_spec is None:
            return None
        if self.run_mode_spec.startswith(
            (
                "resume_appendix_g_full_simulation_lane_missing_cells__",
                "run_appendix_g_full_simulation_lane_missing_cells__",
            )
        ):
            return 1
        return None

    @property
    def target_progress_checkpoint_chunk_size_matches_targeted_resume(self) -> bool:
        expected_chunk_size = self.targeted_resume_expected_chunk_size
        return (
            expected_chunk_size is not None
            and self.target_progress_checkpoint_chunk_size is not None
            and self.target_progress_checkpoint_chunk_size == expected_chunk_size
        )

    @property
    def target_progress_checkpoint_chunk_size_drifted(self) -> bool:
        expected_chunk_size = self.targeted_resume_expected_chunk_size
        return (
            expected_chunk_size is not None
            and self.target_progress_checkpoint_chunk_size is not None
            and self.target_progress_checkpoint_chunk_size != expected_chunk_size
        )

    @property
    def latest_observed_log_tail(self) -> str | None:
        explicit_tail = getattr(self, "_latest_observed_log_tail", None)
        if isinstance(explicit_tail, property):
            explicit_tail = None
        if explicit_tail is not None:
            return explicit_tail
        return _appendix_g_latest_observed_log_tail(self)

    @latest_observed_log_tail.setter
    def latest_observed_log_tail(self, value: str | None) -> None:
        if isinstance(value, property):
            value = None
        object.__setattr__(self, "_latest_observed_log_tail", value)

    @property
    def latest_observed_log_tail_successful_draw_count(self) -> int | None:
        explicit_count = getattr(
            self, "_latest_observed_log_tail_successful_draw_count", None
        )
        if isinstance(explicit_count, property):
            explicit_count = None
        if explicit_count is not None:
            return explicit_count
        successful_draws, _ = _appendix_g_log_tail_counts(self.latest_observed_log_tail)
        return successful_draws

    @latest_observed_log_tail_successful_draw_count.setter
    def latest_observed_log_tail_successful_draw_count(self, value: int | None) -> None:
        if isinstance(value, property):
            value = None
        object.__setattr__(
            self,
            "_latest_observed_log_tail_successful_draw_count",
            value,
        )

    @property
    def latest_observed_log_tail_attempt_index(self) -> int | None:
        explicit_attempt_index = getattr(
            self, "_latest_observed_log_tail_attempt_index", None
        )
        if isinstance(explicit_attempt_index, property):
            explicit_attempt_index = None
        if explicit_attempt_index is not None:
            return explicit_attempt_index
        _, attempt_index = _appendix_g_log_tail_counts(self.latest_observed_log_tail)
        return attempt_index

    @latest_observed_log_tail_attempt_index.setter
    def latest_observed_log_tail_attempt_index(self, value: int | None) -> None:
        if isinstance(value, property):
            value = None
        object.__setattr__(
            self,
            "_latest_observed_log_tail_attempt_index",
            value,
        )

    @property
    def exact_resume_runner_monitor_gate(self) -> bool:
        return (
            self.request_artifact_matches_target
            and self.run_mode_spec is not None
            and self.run_mode_spec.startswith(
                "resume_appendix_g_full_simulation_lane_missing_cells__"
            )
            and self.active_matching_runner_count == 1
            and not self.launch_ready
            and self.target_progress_checkpoint_present
            and (
                not self.target_progress_checkpoint_chunk_size_drifted
                or (
                    self.same_pid_stale_runner_suspected
                    and self.controlled_stop_contract_ready
                )
            )
            and self.target_progress_successful_draw_count is not None
            and not self.target_results_checkpoint_present
            and not self.target_efficiency_checkpoint_present
        )

    @property
    def monitor_contract_ready(self) -> bool:
        return (
            self.exact_resume_runner_monitor_gate
            and self.runner_recovered_monitor_plan_present
            and not self.same_pid_stale_runner_suspected
            and not self.controlled_stop_contract_ready
            and not self.phase_handoff_live_request_drifted
            and self.controlled_stop_decision_outcome == "runner_recovered_before_stop"
            and self.controlled_stop_recommended_action == "monitor_existing_runner"
        )

    @property
    def exact_route_drifted(self) -> bool:
        return (
            not (
                self.target_results_checkpoint_present
                and self.target_efficiency_checkpoint_present
            )
            and not (
                self.same_pid_stale_runner_suspected
                and self.controlled_stop_contract_ready
            )
            and not self.resume_ready_gate_reopened
            and not self.monitor_contract_ready
        )

    @property
    def resume_ready_gate_reopened(self) -> bool:
        return (
            self.request_artifact_matches_target
            and self.run_mode_spec is not None
            and self.run_mode_spec.startswith(
                "resume_appendix_g_full_simulation_lane_missing_cells__"
            )
            and self.active_matching_runner_count == 0
            and self.launch_ready
            and self.target_progress_checkpoint_present
            and not self.target_progress_checkpoint_chunk_size_drifted
            and not self.target_results_checkpoint_present
            and not self.target_efficiency_checkpoint_present
        )

    @property
    def current_outcome(self) -> str:
        if (
            self.target_results_checkpoint_present
            and self.target_efficiency_checkpoint_present
        ):
            return "cell_completed"
        if self.same_pid_stale_runner_suspected and self.controlled_stop_contract_ready:
            return "stale_runner_suspicion_reopened"
        if self.resume_ready_gate_reopened:
            return "runner_exited_resume_ready_without_stop"
        if self.monitor_contract_ready:
            return "runner_recovered_before_stop"
        if self.exact_route_drifted:
            return "recovered_monitor_route_drifted"
        return "recovered_monitor_route_drifted"

    @property
    def recommended_action(self) -> str:
        if self.current_outcome == "cell_completed":
            return "reprobe_next_residual_cell"
        if self.current_outcome == "stale_runner_suspicion_reopened":
            return "follow_controlled_stop_contingency"
        if self.current_outcome == "runner_exited_resume_ready_without_stop":
            return "resume_existing_checkpoint"
        if self.current_outcome == "runner_recovered_before_stop":
            if self.phase_handoff_second_bounded_monitor_forbidden:
                return (
                    self.phase_handoff_recommended_action
                    or "continue_monitor_existing_runner"
                )
            return "bounded_monitor_existing_runner"
        return "repair_shared_truth_before_monitor"

    @property
    def recovered_monitor_current_outcome(self) -> str:
        return self.current_outcome

    @property
    def recovered_monitor_recommended_action(self) -> str:
        return self.recommended_action


