    @property
    def live_target_current_head_marker(self) -> str | None:
        return (
            self.helper_only_current_head_marker
            or self.attached_runner_current_head_marker
        )

    @property
    def effective_progress_floor_is_conservative(self) -> bool:
        return (
            self.progress_floor_is_conservative
            or self.helper_only_reprobe
            or self.execute_guidance_action == "repair_shared_truth_before_monitor"
            or self.current_head_outruns_bounded_monitor_floor
        )

    @staticmethod
    def _progress_count_from_marker(marker: str | None) -> int | None:
        if marker is None:
            return None
        parts = [part.strip() for part in marker.split("/")]
        for part in parts:
            if re.fullmatch(r"\d+", part):
                return int(part)
        return None

    @property
    def current_head_outruns_bounded_monitor_floor(self) -> bool:
        current_head_count = self._progress_count_from_marker(
            self.helper_only_current_head_marker
            or self.attached_runner_current_head_marker
        )
        bounded_floor_count = self._progress_count_from_marker(
            self.bounded_monitor_floor_timestamp
        )
        return (
            current_head_count is not None
            and bounded_floor_count is not None
            and current_head_count > bounded_floor_count
        )

    @property
    def phase_handoff_progress_floor_lag(self) -> int | None:
        if self.progress_floor_lag is not None:
            return self.progress_floor_lag
        bounded_floor_count = self._progress_count_from_marker(
            self.bounded_monitor_floor_timestamp
        )
        if (
            self.target_progress_successful_draw_count is None
            or bounded_floor_count is None
        ):
            return None
        return self.target_progress_successful_draw_count - bounded_floor_count

    @property
    def phase_handoff_remaining_draw_lead(self) -> int | None:
        if self.remaining_draw_lead is not None:
            return self.remaining_draw_lead
        return self.phase_handoff_progress_floor_lag

    @property
    def phase_handoff_live_request_drifted(self) -> bool:
        if self.live_request_drifted is not None:
            return bool(self.live_request_drifted)
        progress_floor_lag = self.phase_handoff_progress_floor_lag
        remaining_draw_lead = self.phase_handoff_remaining_draw_lead
        return (
            progress_floor_lag is not None
            and progress_floor_lag > _APPENDIX_G_RELOCK_LIVE_DRIFT_TOLERANCE
        ) or (
            remaining_draw_lead is not None
            and remaining_draw_lead > _APPENDIX_G_RELOCK_LIVE_DRIFT_TOLERANCE
        )

    @property
    def phase_handoff_progress_floor_matches_live_request(self) -> bool:
        progress_floor_lag = self.phase_handoff_progress_floor_lag
        return (
            progress_floor_lag <= _APPENDIX_G_RELOCK_LIVE_DRIFT_TOLERANCE
            if progress_floor_lag is not None
            else False
        )

    @property
    def phase_handoff_remaining_draw_floor_matches_live_request(self) -> bool:
        remaining_draw_lead = self.phase_handoff_remaining_draw_lead
        return (
            remaining_draw_lead <= _APPENDIX_G_RELOCK_LIVE_DRIFT_TOLERANCE
            if remaining_draw_lead is not None
            else False
        )

    @property
    def phase_handoff_read_only_confirmation_marker(self) -> str | None:
        value = self.read_only_confirmation_marker
        if isinstance(value, str) and value.strip() in {"", "None"}:
            value = None
        if value is None:
            return self.live_target_current_head_marker
        return value

    @property
    def phase_handoff_second_bounded_monitor_forbidden(self) -> bool:
        return self.second_bounded_monitor_forbidden

    @property
    def phase_handoff_current_head_outruns_bounded_monitor_floor(self) -> bool:
        return self.current_head_outruns_bounded_monitor_floor

    @property
    def honest_multi_runner_monitor_head(self) -> bool:
        return (
            self.routing_action == "monitor_existing_runner"
            and self.active_matching_runner_count is not None
            and self.active_matching_runner_count > 1
            and not self.helper_only_reprobe
            and self.same_pid_stale_runner_suspected is not True
        )

    @property
    def recommended_action(self) -> str | None:
        stale_runner_with_execute_guidance = (
            self.same_pid_stale_runner_suspected is True
            and self.execute_guidance_action is not None
        )
        if (
            self.phase_handoff_live_request_drifted
            and self.current_head_outruns_bounded_monitor_floor
            and not self.honest_multi_runner_monitor_head
            and not stale_runner_with_execute_guidance
        ):
            return "repair_shared_truth_before_monitor"
        if self.execute_guidance_action is not None:
            return self.execute_guidance_action
        if self.window_action is not None:
            return self.window_action
        if (
            self.second_bounded_monitor_forbidden
            and self.routing_action == "monitor_existing_runner"
        ):
            return "continue_monitor_existing_runner"
        return self.routing_action

    @property
    def public_next_step(self) -> str | None:
        return _first_non_none(
            self.live_oracle_public_next_step,
            self.execute_guidance_action,
            self.follow_on_action,
            self.phase_handoff_recommended_action,
        )

    @property
    def latest_finish_observability_healthy(self) -> bool | None:
        return self.live_oracle_latest_finish_observability_healthy

    @property
    def same_packet_reclaim_forbidden(self) -> bool | None:
        return self.live_oracle_same_packet_reclaim_forbidden

    @property
    def latest_finish_role(self) -> str | None:
        return self.live_oracle_latest_finish_role

    @property
    def latest_finish_timestamp(self) -> str | None:
        return self.live_oracle_latest_finish_timestamp

    @property
    def latest_finish_inbox_path(self) -> str | None:
        return self.live_oracle_latest_finish_inbox_path

    @property
    def latest_finish_run_report_path(self) -> str | None:
        return self.live_oracle_latest_finish_run_report_path

    @property
    def latest_finish_phase_handoff_action_target_marker(self) -> str | None:
        return self.live_oracle_latest_finish_phase_handoff_action_target_marker

    @property
    def shared_truth_timestamp_outruns_latest_finish(self) -> bool | None:
        return self.live_oracle_shared_truth_timestamp_outruns_latest_finish

    @property
    def automation_observability_is_healthy(self) -> bool | None:
        return self.live_oracle_automation_observability_is_healthy

    @property
    def automation_observability_drift_reasons(self) -> tuple[str, ...]:
        return tuple(self.live_oracle_automation_observability_drift_reasons)

    @property
    def documented_shared_truth_marker(self) -> str | None:
        return _first_non_none(
            self.live_oracle_documented_shared_truth_marker,
            self.phase_handoff_action_target_marker,
            self.phase_handoff_read_only_confirmation_marker,
            self.live_target_current_head_marker,
            self.phase_handoff_bounded_monitor_floor,
        )

    @property
    def blocker_class(self) -> str | None:
        return self.live_oracle_blocker_class

    @property
    def legal_next_step(self) -> str | None:
        return _first_non_none(
            self.live_oracle_legal_next_step,
            self.live_oracle_public_next_step,
            self.phase_handoff_recommended_action,
            self.follow_on_action,
        )

    @property
    def owner(self) -> str | None:
        return _first_non_none(
            self.live_oracle_blocker_owner,
            (
                "correct_course"
                if self.legal_next_step == "repair_shared_truth_before_monitor"
                else "main_exec"
                if self.legal_next_step is not None
                else None
            ),
        )

    @property
    def next_command(self) -> str | None:
        return self.live_oracle_blocker_next_command_shell

    @property
    def exit_criteria(self) -> str | None:
        if self.live_oracle_blocker_exit_criteria is not None:
            return self.live_oracle_blocker_exit_criteria
        if self.legal_next_step == "repair_shared_truth_before_monitor":
            return _APPENDIX_G_SHARED_TRUTH_REPAIR_EXIT_CRITERIA
        return _APPENDIX_G_TARGET_MATERIALIZATION_EXIT_CRITERIA


