    @property
    def target_remaining_successful_draw_count(self) -> int | None:
        return self.live_target_remaining_successful_draw_count

    @property
    def live_target_progress_floor_lag(self) -> int | None:
        if (
            self.live_target_progress_successful_draw_count is None
            or self.documented_target_progress_successful_draw_count is None
        ):
            return None
        return (
            self.live_target_progress_successful_draw_count
            - self.documented_target_progress_successful_draw_count
        )

    @property
    def live_target_remaining_draw_lead(self) -> int | None:
        if (
            self.live_target_remaining_successful_draw_count is None
            or self.documented_target_remaining_successful_draw_count is None
        ):
            return None
        return (
            self.documented_target_remaining_successful_draw_count
            - self.live_target_remaining_successful_draw_count
        )

    @property
    def live_target_shared_truth_drifted(self) -> bool:
        return any(
            value is not None and value > 0
            for value in (
                self.live_target_progress_floor_lag,
                self.live_target_remaining_draw_lead,
            )
        )

