_LOG_FAILURE_RE = re.compile(
    r"^(?P<message>.+?)\s*$\n^r\((?P<rc>\d+)\);$", re.MULTILINE
)
_ABSOLUTE_PROJECT_PATH_RE = re.compile(r"/Users/cxy/Desktop/2026project/[^\s\"'`]+")
_FRESH_LOG_CLOSE_SKEW_SECONDS = 2.0
_DOCUMENTED_MTIME_FORMAT = "%Y-%m-%d %H:%M:%S %z"


def _extract_latest_log_failure(log_text: str) -> tuple[str | None, int | None]:
    latest_error: str | None = None
    latest_rc: int | None = None
    for match in _LOG_FAILURE_RE.finditer(log_text):
        message = match.group("message").strip()
        if message.lower() == "end of do-file":
            continue
        latest_error = message
        latest_rc = int(match.group("rc"))
    return latest_error, latest_rc


def _has_legacy_absolute_root(text: str) -> bool:
    return any(fragment in text for fragment in FORBIDDEN_WORKTREE_FRAGMENTS)


def _has_external_absolute_root(text: str, project_root: Path) -> bool:
    root_prefix = project_root.as_posix()
    for match in _ABSOLUTE_PROJECT_PATH_RE.finditer(text):
        absolute_path = match.group(0)
        if not absolute_path.startswith(root_prefix):
            return True
    return False


def _latest_log_failure(
    root: Path, log_paths: tuple[str, ...]
) -> tuple[str | None, int | None]:
    latest_error: str | None = None
    latest_rc: int | None = None
    for relative_path in log_paths:
        log_path = root / relative_path
        if not log_path.exists():
            continue
        latest_error, latest_rc = _extract_latest_log_failure(
            log_path.read_text(encoding="utf-8")
        )
    return latest_error, latest_rc


def _latest_regex_capture(text: str, pattern: str) -> str | None:
    latest: str | None = None
    for match in re.finditer(pattern, text):
        latest = match.group(1)
    return latest


def _latest_regex_capture_any_group(text: str, pattern: str) -> str | None:
    latest: str | None = None
    for match in re.finditer(pattern, text):
        for captured in match.groups():
            if captured is not None:
                latest = captured.strip()
                break
    return latest


def _latest_regex_int(text: str, pattern: str) -> int | None:
    captured = _latest_regex_capture(text, pattern)
    return int(captured) if captured is not None else None


def _latest_regex_documented_mtime(text: str, pattern: str) -> float | None:
    captured = _latest_regex_capture(text, pattern)
    if captured is None:
        return None
    try:
        return datetime.strptime(captured, _DOCUMENTED_MTIME_FORMAT).timestamp()
    except ValueError:
        return None


def _normalize_automation_role_token(role: str | None) -> str | None:
    if role is None:
        return None
    stripped = role.strip()
    if not stripped:
        return None
    return stripped.replace("-", "_")


def _normalize_automation_timestamp_literal(timestamp: str | None) -> str | None:
    if timestamp is None:
        return None
    stripped = timestamp.strip().strip("'").strip('"')
    if not stripped:
        return None
    for fmt in ("%Y-%m-%dT%H:%M:%S%z",):
        try:
            return datetime.strptime(stripped, fmt).strftime("%Y-%m-%dT%H:%M:%S%z")
        except ValueError:
            continue
    return stripped


def _automation_state_workers_last_run_items(
    automation_state_text: str,
) -> tuple[tuple[str, str], ...]:
    if not automation_state_text:
        return ()
    block_match = re.search(
        r"(?ms)^workers:\n(?:^[ ]{2}.*\n)*?^[ ]{2}last_run:\n(?P<block>(?:^[ ]{4}[A-Za-z0-9_-]+:\s*(?:\"[^\"]+\"|[^\"\n#][^\n#]*)\s*$\n?)*)",
        automation_state_text,
    )
    if block_match is None:
        return ()
    normalized_items: dict[str, str] = {}
    ordered_keys: list[str] = []
    for line in block_match.group("block").splitlines():
        match = re.match(
            r'^[ ]{4}([A-Za-z0-9_-]+):\s*(?:"([^"]+)"|([^"\n#][^\n#]*))\s*$',
            line,
        )
        if match is None:
            continue
        key = _normalize_automation_role_token(match.group(1))
        if key is None:
            continue
        value = next(
            (captured.strip() for captured in match.groups()[1:] if captured is not None),
            "",
        )
        value = _normalize_automation_timestamp_literal(value) or value
        if key not in ordered_keys:
            ordered_keys.append(key)
        normalized_items[key] = value
    return tuple((key, normalized_items[key]) for key in ordered_keys)


def _read_text_if_exists(path: Path) -> str:
    if not path.is_file():
        return ""
    return path.read_text(encoding="utf-8")


def _path_stat_token(path: Path) -> tuple[bool, int | None, int | None]:
    try:
        stat = path.stat()
    except OSError:
        return (False, None, None)
    return (True, stat.st_mtime_ns, stat.st_size)


def _write_text_atomic(path: Path, text: str) -> Path:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp_path = path.with_name(f"{path.name}.tmp-{os.getpid()}-{time.time_ns()}")
    try:
        with tmp_path.open("w", encoding="utf-8") as handle:
            handle.write(text)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(tmp_path, path)
    finally:
        if tmp_path.exists():
            tmp_path.unlink()
    return path


def write_automation_paired_markdown_artifacts_atomic(
    project_root: str | Path,
    *,
    role: str,
    finish_timestamp: str,
    inbox_text: str,
    run_report_text: str,
) -> tuple[str, str]:
    root = Path(project_root)
    observability_name = _automation_state_observability_section_name(
        role,
        finish_timestamp,
    )
    if observability_name is None:
        raise ValueError(
            "Could not derive an observability artifact name from the finish timestamp."
        )

    inbox_path = (
        root / "_bmad-output" / "automation" / "inbox" / observability_name
    )
    run_report_path = (
        root / "_bmad-output" / "automation" / "run-reports" / observability_name
    )
    for key, value in (
        ("latest_finish_inbox_path", inbox_path.as_posix()),
        ("latest_finish_run_report_path", run_report_path.as_posix()),
    ):
        pattern = re.compile(rf"(?m)^- {re.escape(key)}: .*$")
        replacement = f"- {key}: `{value}`"
        inbox_text = pattern.sub(replacement, inbox_text)
        run_report_text = pattern.sub(replacement, run_report_text)
    _write_text_atomic(inbox_path, inbox_text)
    _write_text_atomic(run_report_path, run_report_text)
    return inbox_path.as_posix(), run_report_path.as_posix()


def _yaml_top_level_block_scalar_present(text: str, key: str) -> bool:
    return (
        re.search(
            rf"(?m)^{re.escape(key)}:\s*(?:>|\|)[-+]?\n",
            text,
        )
        is not None
    )


def _yaml_top_level_block_scalar_body(text: str, key: str) -> str:
    match = re.search(
        rf"(?ms)^{re.escape(key)}:\s*(?:>|\|)[-+]?\n(?P<body>(?:^[ ]{{2}}.*(?:\n|$))*)",
        text,
    )
    if match is None:
        return ""
    body_lines = []
    for line in match.group("body").splitlines():
        if line.startswith("  "):
            body_lines.append(line[2:])
        else:
            body_lines.append(line)
    return "\n".join(body_lines).strip()


def _current_phase_inventory_dir(root: Path) -> Path | None:
    state_path = root / ".planning/STATE.md"
    state_text = _read_text_if_exists(state_path)
    match = re.search(r"(?m)^- Current Phase:\s*(\d+)\s*$", state_text)
    if match is None:
        return None

    phase_root = root / ".planning/phases"
    if not phase_root.is_dir():
        return None

    phase_prefix = f"{int(match.group(1)):02d}-"
    phase_dirs = sorted(
        path
        for path in phase_root.iterdir()
        if path.is_dir() and path.name.startswith(phase_prefix)
    )
    return phase_dirs[0] if phase_dirs else None


def _latest_phase_inventory_labels_for_root(
    root: Path,
) -> tuple[str | None, str | None]:
    phase_dir = _current_phase_inventory_dir(root)
    if phase_dir is None:
        return (None, None)

    summary_labels: list[tuple[int, str]] = []
    plan_labels: list[tuple[int, str]] = []
    for path in phase_dir.iterdir():
        match = re.fullmatch(r"\d{2}-(\d+)-(PLAN|SUMMARY)\.md", path.name)
        if match is None:
            continue
        label = (int(match.group(1)), path.name)
        if match.group(2) == "SUMMARY":
            summary_labels.append(label)
        else:
            plan_labels.append(label)

    latest_summary = max(summary_labels)[1] if summary_labels else None
    latest_plan = max(plan_labels)[1] if plan_labels else None
    return latest_summary, latest_plan


def _current_phase_identity(root: Path) -> tuple[str | None, str | None]:
    phase_dir = _current_phase_inventory_dir(root)
    if phase_dir is None:
        return (None, None)

    state_text = _read_text_if_exists(root / ".planning/STATE.md")
    number_match = re.search(r"(?m)^- Current Phase:\s*(\d+)\s*$", state_text)
    name_match = re.search(r"(?m)^- Current Phase Name:\s*(.+?)\s*$", state_text)
    if number_match is None or name_match is None:
        return (None, None)

    phase_number = int(number_match.group(1))
    phase_name = name_match.group(1).strip()
    _, _, phase_suffix = phase_dir.name.partition("-")
    if not phase_suffix:
        return (None, None)

    return (
        f"phase-{phase_number}-{phase_suffix}",
        f"Phase {phase_number}: {phase_name}",
    )


def _latest_run_log_finish_event_for_root(
    root: Path,
) -> tuple[dict[str, object] | None, str | None]:
    run_log_path = root / "_bmad-output/automation/run-log.ndjson"
    if not run_log_path.is_file():
        return None, f"missing:{run_log_path.as_posix()}"

    cache = globals().setdefault("_LATEST_RUN_LOG_FINISH_EVENT_CACHE", {})
    cache_key = str(run_log_path.resolve())
    stat = run_log_path.stat()
    cache_token = (stat.st_mtime_ns, stat.st_size)
    cached = cache.get(cache_key)
    if cached is not None and cached[0] == cache_token:
        return cached[1], cached[2]

    finish_events: list[dict[str, object]] = []
    latest_timestamped_finish_event: dict[str, object] | None = None
    latest_timestamped_finish_datetime: datetime | None = None
    for line_number, line in enumerate(
        run_log_path.read_text(encoding="utf-8").splitlines(),
        start=1,
    ):
        if not line.strip():
            continue
        try:
            record = json.loads(line)
        except json.JSONDecodeError as exc:
            error = f"line {line_number}: {exc.msg}"
            cache[cache_key] = (cache_token, None, error)
            return None, error
        if isinstance(record, dict) and record.get("event") == "finish":
            finish_events.append(record)
            timestamp_literal = record.get("timestamp")
            if not isinstance(timestamp_literal, str):
                continue
            try:
                finish_datetime = datetime.strptime(
                    timestamp_literal,
                    "%Y-%m-%dT%H:%M:%S%z",
                )
            except ValueError:
                continue
            if (
                latest_timestamped_finish_datetime is None
                or finish_datetime >= latest_timestamped_finish_datetime
            ):
                latest_timestamped_finish_event = record
                latest_timestamped_finish_datetime = finish_datetime

    if not finish_events:
        cache[cache_key] = (cache_token, None, None)
        return None, None
    if latest_timestamped_finish_event is not None:
        cache[cache_key] = (cache_token, latest_timestamped_finish_event, None)
        return latest_timestamped_finish_event, None
    latest_finish_event = finish_events[-1]
    cache[cache_key] = (cache_token, latest_finish_event, None)
    return latest_finish_event, None


def _invalidate_latest_run_log_finish_event_cache(run_log_path: Path) -> None:
    cache = globals().setdefault("_LATEST_RUN_LOG_FINISH_EVENT_CACHE", {})
    try:
        cache_key = str(run_log_path.resolve())
    except OSError:
        cache_key = str(run_log_path)
    cache.pop(cache_key, None)


def _rewrite_automation_latest_finish_event_atomic(
    project_root: str | Path,
    *,
    role: str,
    finish_timestamp: str,
    event_payload: Mapping[str, object],
) -> str | None:
    root = Path(project_root)
    run_log_path = root / "_bmad-output/automation/run-log.ndjson"
    if not run_log_path.is_file():
        return None

    lines = run_log_path.read_text(encoding="utf-8").splitlines()
    target_index: int | None = None
    records_by_index: dict[int, dict[str, object]] = {}
    for index, line in enumerate(lines):
        if not line.strip():
            continue
        try:
            record = json.loads(line)
        except json.JSONDecodeError:
            return None
        if not isinstance(record, dict):
            continue
        records_by_index[index] = record
        if (
            record.get("event") == "finish"
            and str(record.get("role")) == role
            and str(record.get("timestamp")) == finish_timestamp
        ):
            target_index = index

    if target_index is None:
        return None

    updated_event = dict(records_by_index[target_index])
    updated_event.update(event_payload)
    updated_event["event"] = "finish"
    updated_event["role"] = role
    updated_event["timestamp"] = finish_timestamp
    lines[target_index] = json.dumps(updated_event, ensure_ascii=False, sort_keys=True)
    _write_text_atomic(run_log_path, "\n".join(lines) + "\n")
    _invalidate_latest_run_log_finish_event_cache(run_log_path)
    return run_log_path.as_posix()


def _write_automation_latest_finish_event_atomic(
    project_root: str | Path,
    *,
    role: str,
    finish_timestamp: str,
    event_payload: Mapping[str, object],
) -> str | None:
    root = Path(project_root)
    run_log_path = root / "_bmad-output/automation/run-log.ndjson"
    if not run_log_path.is_file():
        return None

    rewritten_path = _rewrite_automation_latest_finish_event_atomic(
        root,
        role=role,
        finish_timestamp=finish_timestamp,
        event_payload=event_payload,
    )
    if rewritten_path is not None:
        return rewritten_path

    record = dict(event_payload)
    record["event"] = "finish"
    record["role"] = role
    record["timestamp"] = finish_timestamp
    existing_text = run_log_path.read_text(encoding="utf-8")
    separator = "" if not existing_text or existing_text.endswith("\n") else "\n"
    updated_text = (
        existing_text
        + separator
        + json.dumps(record, ensure_ascii=False, sort_keys=True)
        + "\n"
    )
    _write_text_atomic(run_log_path, updated_text)
    _invalidate_latest_run_log_finish_event_cache(run_log_path)
    return run_log_path.as_posix()


def _appendix_g_documented_truth_datetime(
    timestamp_literal: str | None,
) -> datetime | None:
    if not timestamp_literal:
        return None
    normalized = str(timestamp_literal).strip()
    candidates = [normalized]
    marker_match = re.match(
        r"(\d{4}-\d{2}-\d{2} \d{2}:\d{2}(?::\d{2})? [+-]\d{4})",
        normalized,
    )
    if marker_match is not None:
        candidates.append(marker_match.group(1))
    for candidate in candidates:
        for pattern in ("%Y-%m-%d %H:%M %z", "%Y-%m-%d %H:%M:%S %z"):
            try:
                return datetime.strptime(candidate, pattern)
            except ValueError:
                continue
    return None


def _appendix_g_finish_timestamp_not_before_shared_truth_marker(
    finish_timestamp: str,
    *marker_literals: object | None,
) -> str:
    normalized_finish_timestamp = (
        _normalize_automation_timestamp_literal(finish_timestamp) or finish_timestamp
    )
    try:
        finish_datetime = datetime.strptime(
            normalized_finish_timestamp,
            "%Y-%m-%dT%H:%M:%S%z",
        )
    except ValueError:
        finish_datetime = None

    marker_datetimes = tuple(
        marker_datetime
        for marker_datetime in (
            _appendix_g_documented_truth_datetime(
                None if marker_literal is None else str(marker_literal)
            )
            for marker_literal in marker_literals
        )
        if marker_datetime is not None
    )
    if not marker_datetimes:
        return normalized_finish_timestamp

    freshest_marker_datetime = max(marker_datetimes)
    if finish_datetime is None or freshest_marker_datetime > finish_datetime:
        return freshest_marker_datetime.strftime("%Y-%m-%dT%H:%M:%S%z")
    return normalized_finish_timestamp


def _finish_artifacts_pending_rerun_segments(*texts: str) -> tuple[str, ...]:
    canonical_pending_segment = "PENDING rerun after run-log / automation-state sync."
    pending_patterns = (
        r"__rerun_result_placeholder__",
        r"\bgreen pending after this\b",
        r"\bpending rerun\b",
        r"\bpost-closeout observability rerun pending\b",
        r"\bpost-write repo-health verification running immediately after paired closeout append\b",
        r"\brerun pending after this\b",
        r"\bpending immediate execution\b",
        r"\bimmediately rerunning\b",
        r"\bprovisional\b",
    )
    pending_segments: list[str] = []
    for text in texts:
        rerun_segments = re.findall(r"(?mi)^-?\s*rerun_result:\s*(.+)$", text)
        for segment in rerun_segments:
            normalized_segment = str(segment).strip()
            if (
                normalized_segment.startswith("`")
                and normalized_segment.endswith("`")
                and len(normalized_segment) >= 2
            ):
                normalized_segment = normalized_segment[1:-1].strip()
            lowered = normalized_segment.lower()
            if any(re.search(pattern, lowered) is not None for pattern in pending_patterns):
                if canonical_pending_segment not in pending_segments:
                    pending_segments.append(canonical_pending_segment)
    return tuple(pending_segments)


def _finish_artifacts_leave_post_closeout_rerun_pending(*texts: str) -> bool:
    return bool(_finish_artifacts_pending_rerun_segments(*texts))


def _finish_artifacts_report_contradictory_rerun_health_claim(*texts: str) -> bool:
    rerun_claims_healthy = False
    packet_requires_shared_truth_repair = False

    for text in texts:
        rerun_segments = re.findall(r"(?mi)^-?\s*rerun_result:\s*(.+)$", text)
        for segment in rerun_segments:
            lowered_segment = segment.lower()
            if (
                "is_healthy=true" in lowered_segment
                or "is_healthy == true" in lowered_segment
            ):
                rerun_claims_healthy = True

        packet_requires_shared_truth_repair = (
            packet_requires_shared_truth_repair
            or (
                re.search(
                    r"(?mi)^-?\s*legal_next_step:\s*`?repair_shared_truth_before_monitor`?\s*$",
                    text,
                )
                is not None
                and (
                    re.search(
                        r"(?mi)^-?\s*latest_finish_observability_healthy:\s*`?false`?\s*$",
                        text,
                    )
                    is not None
                    or re.search(
                        r"(?mi)^-?\s*same_packet_reclaim_forbidden:\s*`?false`?\s*$",
                        text,
                    )
                    is not None
                )
            )
        )

    return rerun_claims_healthy and packet_requires_shared_truth_repair


def _finish_artifacts_report_historical_supersede(*texts: str) -> bool:
    for text in texts:
        rerun_segments = re.findall(r"(?mi)^-?\s*rerun_result:\s*(.+)$", text)
        for segment in rerun_segments:
            if "historical supersede" in segment.lower():
                return True
    return False


def _finish_event_paired_artifact_paths(
    root: Path,
    finish_event: dict[str, object],
) -> tuple[Path, ...]:
    paths: list[Path] = []
    for primary_key, fallback_key in (
        ("paired_inbox", "latest_finish_inbox_path"),
        ("paired_run_report", "latest_finish_run_report_path"),
    ):
        path_literal = finish_event.get(primary_key)
        if (not isinstance(path_literal, str) or not path_literal.strip()) and (
            isinstance(finish_event.get(fallback_key), str)
            and str(finish_event.get(fallback_key)).strip()
        ):
            path_literal = finish_event.get(fallback_key)
        if not isinstance(path_literal, str) or not path_literal.strip():
            continue
        path = Path(path_literal)
        if not path.is_absolute():
            path = root / path_literal
        paths.append(path)
    return tuple(paths)


def _finish_event_paired_artifact_stat_tokens(
    root: Path,
    finish_event: dict[str, object] | None,
) -> tuple[tuple[object, ...], ...]:
    if not isinstance(finish_event, dict):
        return ()
    return tuple(
        (path.as_posix(), *_path_stat_token(path))
        for path in _finish_event_paired_artifact_paths(root, finish_event)
    )


def _finish_event_paired_artifact_texts(
    root: Path,
    finish_event: dict[str, object],
) -> tuple[str, ...]:
    texts: list[str] = []
    for path in _finish_event_paired_artifact_paths(root, finish_event):
        if path.is_file():
            texts.append(path.read_text(encoding="utf-8"))
    return tuple(texts)


def _finish_event_pair_identifier(root: Path, finish_event: dict[str, object]) -> str:
    for path in _finish_event_paired_artifact_paths(root, finish_event):
        if path.as_posix().startswith(root.as_posix()):
            return path.relative_to(root).as_posix()
        return path.as_posix()
    timestamp_literal = finish_event.get("timestamp")
    return str(timestamp_literal) if timestamp_literal is not None else "unknown-finish"


def _appendix_g_frozen_snapshot_override(root: Path) -> SimpleNamespace | None:
    return _APPENDIX_G_SHARED_TRUTH_RENDER_SNAPSHOT_OVERRIDES.get(str(root.resolve()))


def _appendix_g_frozen_observability_cache_key(
    root: Path,
    *,
    phase_handoff_status: object | None,
    snapshot: object | None,
    request: object | None,
    finish_event: dict[str, object] | None,
) -> tuple[object, ...] | None:
    snapshot_override = _appendix_g_frozen_snapshot_override(root)
    if snapshot_override is None:
        return None
    resolved_snapshot = snapshot if snapshot is not None else snapshot_override
    resolved_request = request if request is not None else getattr(
        resolved_snapshot, "request", None
    )
    resolved_phase_handoff_status = (
        phase_handoff_status
        if phase_handoff_status is not None
        else getattr(resolved_snapshot, "phase_handoff_status", None)
    )
    return (
        id(snapshot_override),
        id(resolved_snapshot),
        id(resolved_request),
        id(resolved_phase_handoff_status),
        _path_stat_token(root / "_bmad-output/automation/run-log.ndjson"),
        _path_stat_token(root / "_bmad-output/automation/automation-state.yaml"),
        _finish_event_paired_artifact_stat_tokens(root, finish_event),
    )


