def _appendix_g_record_phase_handoff_live_observability_status(
    root: Path,
    *,
    phase_handoff_status: object | None,
    request: object | None,
    observability_status: object,
    finish_event: dict[str, object] | None = None,
) -> None:
    cache_key = _appendix_g_phase_handoff_live_observability_cache_key(
        root,
        phase_handoff_status=phase_handoff_status,
        request=request,
        observability_status=observability_status,
        finish_event=finish_event,
    )
    if cache_key is None:
        return
    _APPENDIX_G_PHASE_HANDOFF_LIVE_OBSERVABILITY_STATUS_CACHE[
        str(root.resolve())
    ] = (
        cache_key,
        observability_status,
    )


def _appendix_g_cached_phase_handoff_live_observability_status(
    root: Path,
    *,
    phase_handoff_status: object | None,
    request: object | None,
    finish_event: dict[str, object] | None = None,
) -> object | None:
    cache_key = _appendix_g_phase_handoff_live_observability_cache_key(
        root,
        phase_handoff_status=phase_handoff_status,
        request=request,
        finish_event=finish_event,
    )
    if cache_key is None:
        return None
    cached_status = _APPENDIX_G_PHASE_HANDOFF_LIVE_OBSERVABILITY_STATUS_CACHE.get(
        str(root.resolve())
    )
    if cached_status is not None and cached_status[0] == cache_key:
        return cached_status[1]
    return None


