    def _normalize_marker_literal(value: object | None) -> object | None:
        if isinstance(value, str) and value.strip() in {"", "None"}:
            return None
        return value

    def _freshest_marker_literal(*values: object | None) -> object | None:
        normalized_values = tuple(
            value for value in (_normalize_marker_literal(value) for value in values)
            if value is not None
        )
        dated_values = tuple(
            (marker, _appendix_g_documented_truth_datetime(marker))
            for marker in normalized_values
        )
        dated_values = tuple(
            (marker, marker_datetime)
            for marker, marker_datetime in dated_values
            if marker_datetime is not None
        )
        if dated_values:
            return max(dated_values, key=lambda item: item[1])[0]
        return normalized_values[0] if normalized_values else None

