_STATA_RUNTIME_APP_BUNDLE_COMMAND_FALLBACKS: dict[str, tuple[str, ...]] = {
    "stata-mp": (
        "/Applications/Stata/StataMP.app/Contents/MacOS/stata-mp",
        "/Applications/Stata/StataMP.app/Contents/MacOS/StataMP",
    ),
    "stata-se": (
        "/Applications/Stata/StataSE.app/Contents/MacOS/stata-se",
        "/Applications/Stata/StataSE.app/Contents/MacOS/StataSE",
    ),
    "stata": (
        "/Applications/Stata/Stata.app/Contents/MacOS/stata",
        "/Applications/Stata/Stata.app/Contents/MacOS/Stata",
    ),
}


def _available_stata_runtime_command() -> str | None:
    for command in ("stata-mp", "stata-se", "stata"):
        resolved = shutil.which(command)
        if resolved:
            return resolved
        for candidate in _STATA_RUNTIME_APP_BUNDLE_COMMAND_FALLBACKS.get(command, ()):
            candidate_path = Path(candidate)
            if candidate_path.is_file() and os.access(candidate_path, os.X_OK):
                return str(candidate_path)
    return None


_STATA_RUNTIME_COMMAND_PROBE_ORDER = ("stata-mp", "stata-se", "stata")


def _relative_path_is_within_allowed_roots(
    relative_path: str,
    allowed_roots: tuple[str, ...],
) -> bool:
    normalized_path = Path(relative_path).as_posix().strip("/")
    for allowed_root in allowed_roots:
        normalized_root = Path(allowed_root).as_posix().strip("/")
        if normalized_root and (
            normalized_path == normalized_root
            or normalized_path.startswith(f"{normalized_root}/")
        ):
            return True
    return False


def package_hardening_frontier_status(
    project_root: str | Path,
) -> PackageHardeningFrontierStatus:
    contracts = post_qcteast_prerequisite_contracts(project_root)
    same_worktree_ready_keys = tuple(
        contract.key for contract in contracts if contract.same_worktree_ready
    )
    blocked_keys = tuple(
        contract.key for contract in contracts if not contract.same_worktree_ready
    )
    prerequisite_trio_closed = not blocked_keys
    if prerequisite_trio_closed:
        current_frontier = "broader_monte_carlo_package_wide_regression_expansion"
        next_rung = "rerank_next_same_worktree_higher_rung_slice"
    else:
        current_frontier = "post_qcteast_prerequisite_trio"
        next_rung = blocked_keys[0]
    return PackageHardeningFrontierStatus(
        current_frontier=current_frontier,
        next_rung=next_rung,
        prerequisite_trio_closed=prerequisite_trio_closed,
        same_worktree_ready_keys=same_worktree_ready_keys,
        blocked_keys=blocked_keys,
    )


def broader_package_hardening_frontier_status(
    project_root: str | Path,
) -> BroaderPackageHardeningFrontierStatus:
    prerequisite_status = package_hardening_frontier_status(project_root)
    if not prerequisite_status.prerequisite_trio_closed:
        return BroaderPackageHardeningFrontierStatus(
            current_frontier=prerequisite_status.current_frontier,
            next_rung=prerequisite_status.next_rung,
            portability_install_doc_bundle_closed=False,
            same_worktree_ready_keys=(),
            blocked_keys=prerequisite_status.blocked_keys,
        )

    contracts = broader_package_wide_contracts(project_root)
    same_worktree_ready_keys = tuple(
        contract.key for contract in contracts if contract.same_worktree_ready
    )
    blocked_keys = tuple(
        contract.key for contract in contracts if not contract.same_worktree_ready
    )

    if blocked_keys:
        current_frontier = "package_wide_portability_install_doc_slice"
        next_rung = blocked_keys[0]
        bundle_closed = False
    else:
        current_frontier = "post_portability_install_doc_broader_closeout"
        next_rung = "rerank_next_broader_monte_carlo_package_wide_slice"
        bundle_closed = True

    return BroaderPackageHardeningFrontierStatus(
        current_frontier=current_frontier,
        next_rung=next_rung,
        portability_install_doc_bundle_closed=bundle_closed,
        same_worktree_ready_keys=same_worktree_ready_keys,
        blocked_keys=blocked_keys,
    )


def appendix_g_reduced_result_rows(
    project_root: str | Path,
) -> tuple[AppendixGReducedResultRow, ...]:
    root = Path(project_root)
    results_path = root / _APPENDIX_G_REDUCED_RESULTS_PATH
    if not results_path.exists():
        if _appendix_g_preserved_reduced_trace_available(root):
            return _appendix_g_preserved_reduced_result_rows()
        return ()
    rows = _read_appendix_g_result_rows_from_csv(results_path)
    actual_grid = {(row.n_obs, row.auto1, row.dgp, row.estimator) for row in rows}
    expected_grid = {
        (n_obs, auto1, dgp, estimator)
        for n_obs in (100, 250)
        for auto1 in (0.0, 0.4)
        for dgp in ("PT", "PTT")
        for estimator in ("Double-DID", "DID", "sDID")
    }
    if actual_grid == expected_grid:
        return rows
    if _appendix_g_preserved_reduced_trace_available(root):
        return _appendix_g_preserved_reduced_result_rows()
    return rows


