def appendix_g_repair_shared_truth_before_monitor_snapshot(
    project_root: str | Path | None = None,
) -> dict[str, object]:
    """Expose the current shared-truth repair packet as a machine-readable probe."""

    root = _resolve_project_root(project_root)
    cache_key = str(root.resolve())
    cache = globals().setdefault(
        "_APPENDIX_G_REPAIR_SHARED_TRUTH_STATUS_CACHE",
        {},
    )
    cached_status = cache.get(cache_key)
    if cached_status is not None and time.monotonic() - cached_status[0] <= 2.0:
        return cached_status[1].serializable_route_snapshot

    status = _appendix_g_read_only_repair_shared_truth_before_monitor_status(root)
    cache[cache_key] = (time.monotonic(), status)
    return status.serializable_route_snapshot


def _appendix_g_phase_handoff_observability_stub(
    phase_handoff_status: object | None,
) -> SimpleNamespace:
    return SimpleNamespace(
        is_healthy=bool(
            _first_non_none(
                getattr(
                    phase_handoff_status,
                    "live_oracle_automation_observability_is_healthy",
                    None,
                ),
                getattr(
                    phase_handoff_status,
                    "automation_observability_is_healthy",
                    None,
                ),
                False,
            )
        ),
        shared_truth_timestamp_outruns_latest_finish=bool(
            _first_non_none(
                getattr(
                    phase_handoff_status,
                    "live_oracle_shared_truth_timestamp_outruns_latest_finish",
                    None,
                ),
                getattr(
                    phase_handoff_status,
                    "shared_truth_timestamp_outruns_latest_finish",
                    None,
                ),
                False,
            )
        ),
        latest_finish_timestamp=_first_non_none(
            getattr(phase_handoff_status, "live_oracle_latest_finish_timestamp", None),
            getattr(phase_handoff_status, "latest_finish_timestamp", None),
        ),
    )


