def render_appendix_g_project_active_appg_03_requirement_line(
    project_root: str | Path,
    *,
    checkbox: str = " ",
) -> str:
    root = Path(project_root)
    snapshot = _appendix_g_cached_shared_truth_render_snapshot(root)
    target_request_line = _appendix_g_current_executable_target_request_line(snapshot)
    checkbox_marker = "x" if checkbox.lower() == "x" else " "
    return (
        f"- [{checkbox_marker}] `REQ-APPG-03` — Target result and efficiency "
        "checkpoints for the current executable "
        f"`{target_request_line}` route must exist and be reflected in aggregate exports."
    )


def replace_appendix_g_project_active_requirement_contract(
    existing_text: str,
    project_root: str | Path,
) -> str:
    pattern = re.compile(
        r"(?m)^- \[(?P<checkbox>[ xX])\] `REQ-APPG-03` — .*$"
    )
    match = pattern.search(existing_text)
    if match is None:
        return existing_text
    replacement = render_appendix_g_project_active_appg_03_requirement_line(
        project_root,
        checkbox=match.group("checkbox"),
    )
    return (
        f"{existing_text[: match.start()]}"
        f"{replacement}"
        f"{existing_text[match.end() :]}"
    )


