def render_appendix_g_readiness_residual_risks_section(
    project_root: str | Path,
) -> str:
    root = Path(project_root)
    snapshot = _appendix_g_shared_truth_render_snapshot(root)
    request = snapshot.request
    aggregate_results = (
        "none"
        if snapshot.aggregate_result_export_mtime is None
        or snapshot.aggregate_result_export_row_count is None
        else f"{snapshot.aggregate_result_export_mtime} / {snapshot.aggregate_result_export_row_count}"
    )
    aggregate_efficiency = (
        "none"
        if snapshot.aggregate_efficiency_export_mtime is None
        or snapshot.aggregate_efficiency_export_row_count is None
        else f"{snapshot.aggregate_efficiency_export_mtime} / {snapshot.aggregate_efficiency_export_row_count}"
    )
    reopened_bounded_monitor_contract = getattr(
        snapshot, "phase_handoff_recommended_action", None
    ) == "bounded_monitor_existing_runner" and not bool(
        getattr(snapshot, "phase_handoff_second_bounded_monitor_forbidden", False)
    )

    lines = [
        "## Residual Risks",
        "",
        _appendix_g_preserved_executor_frontier_trace_line(),
        (
            "- target `results` / `efficiency` checkpoints remain absent；aggregate exports "
            f"only keep `{aggregate_results}` and `{aggregate_efficiency}`，所以 materialization "
            "is still incomplete。"
        ),
        (
            (
            "- current route now keeps "
                f"`{request.run_mode_spec}` over floor `{snapshot.bounded_monitor_floor_timestamp}` "
                f"with current head `{snapshot.current_head_marker}`；"
                f"`phase_handoff_recommended_action = {snapshot.phase_handoff_recommended_action}` "
                "and "
                f"`phase_handoff_second_bounded_monitor_forbidden = "
                f"{snapshot.phase_handoff_second_bounded_monitor_forbidden}` mean the next single "
                "bounded-monitor decision stays tied to the same route evidence。"
            )
            if reopened_bounded_monitor_contract
            else (
                "- until a future fresh re-probe reopens a new relock packet, current route still "
                f"stays `{request.run_mode_spec}` over floor `{snapshot.bounded_monitor_floor_timestamp}` "
                f"with current head `{snapshot.current_head_marker}`；"
                f"`phase_handoff_recommended_action = {snapshot.phase_handoff_recommended_action}` "
                "and "
                f"`phase_handoff_second_bounded_monitor_forbidden = "
                f"{snapshot.phase_handoff_second_bounded_monitor_forbidden}` keep the next "
                "bounded-monitor decision evidence-bound。"
            )
        ),
    ]
    return "\n".join(lines) + "\n"


