def render_appendix_g_test_summary_next_steps_section(
    project_root: str | Path,
) -> str:
    root = Path(project_root)
    snapshot = _appendix_g_shared_truth_render_snapshot(root)
    latest_summary_label = snapshot.latest_summary_label or "none"
    latest_plan_label = snapshot.latest_plan_label or "none"
    next_action_sentence = _appendix_g_reprobe_then_relock_guidance_sentence(
        request_artifact_line=snapshot.request.request_artifact_line or "unknown",
        current_head_marker=getattr(snapshot, "current_head_marker", None),
        target_progress_successful_draw_count=getattr(
            snapshot, "target_progress_successful_draw_count", None
        ),
        target_remaining_successful_draw_count=getattr(
            snapshot, "target_remaining_successful_draw_count", None
        ),
        shared_truth_matches_current_head=_appendix_g_shared_truth_matches_current_head(
            snapshot
        ),
        second_bounded_monitor_forbidden=bool(
            getattr(snapshot, "phase_handoff_second_bounded_monitor_forbidden", False)
        ),
    )

    lines = [
        "## Next Steps",
        "",
        _appendix_g_preserved_executor_frontier_trace_line(),
        _appendix_g_preserved_executor_metric_bridge_line(),
        _appendix_g_preserved_batch_1_bridge_line(),
        _appendix_g_preserved_batch_2_bridge_line(),
        _appendix_g_preserved_batch_3_bridge_line(),
        _appendix_g_preserved_batch_4_bridge_line(),
        _appendix_g_preserved_batches_audit_bridge_line(),
        _appendix_g_preserved_queue_contract_bridge_line(),
        f"- next legal action remains {next_action_sentence}",
        (
            "- repo-visible paired closeout must reference "
            f"`{latest_summary_label}` / `{latest_plan_label}` once reruns stay green。"
        ),
    ]
    return "\n".join(lines) + "\n"


