def materialize_appendix_g_shared_truth_narrative_surfaces(
    project_root: str | Path,
    *,
    state_relative_path: str = ".planning/STATE.md",
    roadmap_relative_path: str = ".planning/ROADMAP.md",
    project_relative_path: str = ".planning/PROJECT.md",
    requirements_relative_path: str = ".planning/REQUIREMENTS.md",
    project_context_relative_path: str = "_bmad-output/planning-artifacts/project-context.md",
    readiness_relative_path: str = "_bmad-output/planning-artifacts/readiness-report.md",
    test_summary_relative_path: str = "_bmad-output/implementation-artifacts/tests/test-summary.md",
    story_relative_path: str = (
        "_bmad-output/implementation-artifacts/"
        "2-1-basic-did-and-sdid-moments-with-bootstrap-friendly-results.md"
    ),
) -> tuple[str, ...]:
    root = Path(project_root)
    updated_paths: list[str] = []

    with _appendix_g_frozen_shared_truth_render_snapshot(root):
        state_path = root / state_relative_path
        if state_path.exists():
            existing_text = state_path.read_text(encoding="utf-8")
            updated_text = replace_first_markdown_section(
                existing_text,
                "## Current Evidence Floor",
                render_appendix_g_state_current_evidence_floor_section(root),
            )
            if updated_text != existing_text:
                state_path.write_text(updated_text, encoding="utf-8")
            updated_paths.append(state_relative_path)

        roadmap_path = root / roadmap_relative_path
        if roadmap_path.exists():
            existing_text = roadmap_path.read_text(encoding="utf-8")
            updated_text = replace_first_markdown_section(
                existing_text,
                "## Immediate Next Rung",
                render_appendix_g_roadmap_immediate_next_rung_section(root),
            )
            if (
                "## Phase 5: Tri-Way Parity, Monte Carlo, And Package Hardening"
                in updated_text
                and "**Current Machine Truth:**" in updated_text
            ):
                updated_text = replace_roadmap_phase_5_current_machine_truth_block(
                    updated_text,
                    render_appendix_g_roadmap_phase_5_current_machine_truth_block(root),
                )
            if updated_text != existing_text:
                roadmap_path.write_text(updated_text, encoding="utf-8")
            updated_paths.append(roadmap_relative_path)

        project_path = root / project_relative_path
        if project_path.exists():
            existing_text = project_path.read_text(encoding="utf-8")
            updated_text = replace_first_markdown_section(
                existing_text,
                "## Current Project Reality",
                render_appendix_g_project_current_reality_section(root),
            )
            updated_text = replace_appendix_g_project_active_requirement_contract(
                updated_text,
                root,
            )
            if updated_text != existing_text:
                project_path.write_text(updated_text, encoding="utf-8")
            updated_paths.append(project_relative_path)

        requirements_path = root / requirements_relative_path
        if requirements_path.exists():
            existing_text = requirements_path.read_text(encoding="utf-8")
            updated_text = replace_first_markdown_section(
                existing_text,
                "## Current Non-Negotiable Frontier Facts",
                render_appendix_g_requirements_current_non_negotiable_frontier_facts_section(
                    root
                ),
            )
            if updated_text != existing_text:
                requirements_path.write_text(updated_text, encoding="utf-8")
            updated_paths.append(requirements_relative_path)

        project_context_path = root / project_context_relative_path
        if project_context_path.exists():
            existing_text = project_context_path.read_text(encoding="utf-8")
            updated_text = replace_first_markdown_section(
                existing_text,
                "## Current Planning Frontier",
                render_appendix_g_project_context_current_planning_frontier_section(root),
            )
            updated_text = replace_first_markdown_section(
                updated_text,
                "## Status",
                render_appendix_g_project_context_status_section(root),
            )
            updated_text = replace_first_markdown_section(
                updated_text,
                "## Immediate Next Rung",
                render_appendix_g_project_context_immediate_next_rung_section(root),
            )
            if updated_text != existing_text:
                project_context_path.write_text(updated_text, encoding="utf-8")
            updated_paths.append(project_context_relative_path)

        readiness_path = root / readiness_relative_path
        if readiness_path.exists():
            existing_text = readiness_path.read_text(encoding="utf-8")
            updated_text = replace_first_markdown_section(
                existing_text,
                "## Current Phase Fact Check",
                render_appendix_g_readiness_current_phase_fact_check_section(root),
            )
            updated_text = replace_first_markdown_section(
                updated_text,
                "## Next Story Frontier",
                render_appendix_g_readiness_next_story_frontier_section(root),
            )
            updated_text = replace_first_markdown_section(
                updated_text,
                "## Residual Risks",
                render_appendix_g_readiness_residual_risks_section(root),
            )
            updated_text = replace_first_markdown_section(
                updated_text,
                "## Status",
                render_appendix_g_readiness_status_section(root),
            )
            if updated_text != existing_text:
                readiness_path.write_text(updated_text, encoding="utf-8")
            updated_paths.append(readiness_relative_path)

        readiness_seed_path = root / _APPENDIX_G_STORY_5_2_READINESS_SEED_PATH
        if readiness_seed_path.exists():
            existing_text = readiness_seed_path.read_text(encoding="utf-8")
            updated_text = replace_first_markdown_section(
                existing_text,
                "## Canonical Frontier Override",
                render_appendix_g_story_canonical_frontier_override_section(root),
            )
            updated_text = replace_first_markdown_section(
                updated_text,
                "## Frontier Context",
                render_appendix_g_story_frontier_context_section(root),
            )
            updated_text = remove_first_markdown_section(
                updated_text,
                "## Frontier " "Lock",
            )
            story_status_section = render_appendix_g_story_status_section(root)
            if "## Status\n" in updated_text:
                updated_text = replace_first_markdown_section(
                    updated_text,
                    "## Status",
                    story_status_section,
                )
            else:
                frontier_context_index = updated_text.find("## Frontier Context\n")
                if frontier_context_index != -1:
                    updated_text = (
                        f"{updated_text[:frontier_context_index]}"
                        f"{story_status_section}\n"
                        f"{updated_text[frontier_context_index:]}"
                    )
                else:
                    updated_text = f"{updated_text.rstrip()}\n\n{story_status_section}"
            if updated_text != existing_text:
                readiness_seed_path.write_text(updated_text, encoding="utf-8")
            updated_paths.append(_APPENDIX_G_STORY_5_2_READINESS_SEED_PATH)

        story_path = root / story_relative_path
        if story_path.exists():
            existing_text = story_path.read_text(encoding="utf-8")
            updated_text = replace_first_markdown_section(
                existing_text,
                "## Canonical Frontier Override",
                render_appendix_g_story_canonical_frontier_override_section(root),
            )
            updated_text = replace_first_markdown_section(
                updated_text,
                "## Frontier Context",
                render_appendix_g_story_frontier_context_section(root),
            )
            updated_text = remove_first_markdown_section(
                updated_text,
                "## Frontier " "Lock",
            )
            story_status_section = render_appendix_g_story_status_section(root)
            if "## Status\n" in updated_text:
                updated_text = replace_first_markdown_section(
                    updated_text,
                    "## Status",
                    story_status_section,
                )
            else:
                frontier_context_index = updated_text.find("## Frontier Context\n")
                if frontier_context_index != -1:
                    updated_text = (
                        f"{updated_text[:frontier_context_index]}"
                        f"{story_status_section}\n"
                        f"{updated_text[frontier_context_index:]}"
                    )
                else:
                    updated_text = f"{updated_text.rstrip()}\n\n{story_status_section}"
            if updated_text != existing_text:
                story_path.write_text(updated_text, encoding="utf-8")
            updated_paths.append(story_relative_path)

        bridge_path = root / _APPENDIX_G_MISSING_CELLS_LOG_CHECKPOINT_BRIDGE_PATH
        if bridge_path.exists():
            existing_text = bridge_path.read_text(encoding="utf-8")
            updated_text = replace_first_markdown_section(
                existing_text,
                "## Current Live Bridge Truth",
                render_appendix_g_missing_cells_log_checkpoint_bridge_current_truth_section(
                    root
                ),
            )
            if updated_text != existing_text:
                bridge_path.write_text(updated_text, encoding="utf-8")
            updated_paths.append(_APPENDIX_G_MISSING_CELLS_LOG_CHECKPOINT_BRIDGE_PATH)

        package_root_probe_alias_gap_path = (
            root / _APPENDIX_G_PACKAGE_ROOT_PROBE_ALIAS_GAP_PATH
        )
        if package_root_probe_alias_gap_path.exists():
            updated_text = render_appendix_g_package_root_probe_alias_gap_current_truth(
                root
            )
            existing_text = package_root_probe_alias_gap_path.read_text(
                encoding="utf-8"
            )
            if updated_text != existing_text:
                package_root_probe_alias_gap_path.write_text(
                    updated_text,
                    encoding="utf-8",
                )
            updated_paths.append(_APPENDIX_G_PACKAGE_ROOT_PROBE_ALIAS_GAP_PATH)

        materialization_helper_bridge_path = (
            root / _APPENDIX_G_MATERIALIZATION_HELPER_BRIDGE_PATH
        )
        updated_text = render_appendix_g_materialization_helper_bridge_current_truth(
            root
        )
        existing_text = (
            materialization_helper_bridge_path.read_text(encoding="utf-8")
            if materialization_helper_bridge_path.exists()
            else ""
        )
        if updated_text != existing_text:
            materialization_helper_bridge_path.parent.mkdir(
                parents=True,
                exist_ok=True,
            )
            materialization_helper_bridge_path.write_text(
                updated_text,
                encoding="utf-8",
            )
        updated_paths.append(_APPENDIX_G_MATERIALIZATION_HELPER_BRIDGE_PATH)

        latest_finish_closeout_bridge_path = (
            root / _APPENDIX_G_LATEST_FINISH_CLOSEOUT_BRIDGE_PATH
        )
        updated_text = render_appendix_g_latest_finish_closeout_bridge_current_truth(
            root
        )
        existing_text = (
            latest_finish_closeout_bridge_path.read_text(encoding="utf-8")
            if latest_finish_closeout_bridge_path.exists()
            else ""
        )
        if updated_text != existing_text:
            latest_finish_closeout_bridge_path.parent.mkdir(
                parents=True,
                exist_ok=True,
            )
            latest_finish_closeout_bridge_path.write_text(
                updated_text,
                encoding="utf-8",
            )
        updated_paths.append(_APPENDIX_G_LATEST_FINISH_CLOSEOUT_BRIDGE_PATH)

        for relative_path in materialize_appendix_g_simulation_dgp_contract_artifact(
            root
        ):
            updated_paths.append(relative_path)

        for relative_path in (
            materialize_appendix_g_aggregate_export_verification_contract_artifact(
                root
            )
        ):
            updated_paths.append(relative_path)

        test_summary_path = root / test_summary_relative_path
        if test_summary_path.exists():
            existing_text = test_summary_path.read_text(encoding="utf-8")
            updated_text = replace_first_markdown_section(
                existing_text,
                "## Next Steps",
                render_appendix_g_test_summary_next_steps_section(root),
            )
            updated_text = replace_first_markdown_section(
                updated_text,
                "## Current Story-Prep Verification",
                render_appendix_g_test_summary_current_story_prep_verification_section(
                    root
                ),
            )
            if updated_text != existing_text:
                test_summary_path.write_text(updated_text, encoding="utf-8")
            updated_paths.append(test_summary_relative_path)

    return tuple(updated_paths)


def materialize_appendix_g_shared_truth_primary_surfaces(
    project_root: str | Path,
    *,
    leading_relative_paths: Sequence[str] = (
        _APPENDIX_G_SHARED_TRUTH_PRIMARY_LEADING_RELATIVE_PATHS
    ),
    handoff_relative_path: str = _APPENDIX_G_SHARED_TRUTH_PHASE_HANDOFF_RELATIVE_PATH,
) -> tuple[str, ...]:
    root = Path(project_root)
    updated_paths: list[str] = []

    handoff_path = root / handoff_relative_path
    handoff_exists = handoff_path.exists()
    if handoff_exists:
        existing_text = handoff_path.read_text(encoding="utf-8")
        updated_text = replace_first_markdown_section(
            existing_text,
            "## Current Machine Truth",
            render_appendix_g_current_machine_truth_section(root),
        )
        if updated_text != existing_text:
            handoff_path.write_text(updated_text, encoding="utf-8")

        # A second pass lets recovered-monitor fields re-read the freshly relocked
        # handoff packet instead of preserving a stale drift verdict from the prior file.
        refreshed_text = handoff_path.read_text(encoding="utf-8")
        refreshed_updated_text = replace_first_markdown_section(
            refreshed_text,
            "## Current Machine Truth",
            render_appendix_g_current_machine_truth_section(root),
        )
        annotated_text = annotate_historical_machine_truth_archive(
            refreshed_updated_text
        )
        if annotated_text != refreshed_text:
            handoff_path.write_text(annotated_text, encoding="utf-8")

    leading_block = render_appendix_g_shared_truth_leading_block(
        root, comment_prefix="# "
    )

    for relative_path in leading_relative_paths:
        path = root / relative_path
        if not path.exists():
            continue
        existing_text = path.read_text(encoding="utf-8")
        updated_text = replace_or_prepend_leading_commentary_block(
            existing_text,
            leading_block,
        )
        if updated_text != existing_text:
            path.write_text(updated_text, encoding="utf-8")
        updated_paths.append(relative_path)

    if handoff_exists:
        updated_paths.append(handoff_relative_path)

    return tuple(updated_paths)


def _phase_inventory_number_from_label(label: str | None) -> int | None:
    if label is None:
        return None
    match = re.fullmatch(r"\d{2}-(\d+)-(PLAN|SUMMARY)\.md", label)
    if match is None:
        return None
    return int(match.group(1))


def _appendix_g_latest_phase_inventory_render_values(
    project_root: str | Path,
) -> SimpleNamespace | None:
    root = Path(project_root)
    phase_dir = _current_phase_inventory_dir(root)
    snapshot = _appendix_g_shared_truth_render_snapshot(root)
    latest_summary_label = getattr(snapshot, "latest_summary_label", None)
    latest_plan_label = getattr(snapshot, "latest_plan_label", None)
    if phase_dir is None or latest_summary_label is None or latest_plan_label is None:
        return None

    action_target_marker = (
        getattr(snapshot, "phase_handoff_action_target_marker", None)
        or getattr(snapshot, "phase_handoff_read_only_confirmation_marker", None)
        or getattr(snapshot, "current_head_marker", None)
        or getattr(snapshot, "bounded_monitor_floor_timestamp", None)
    )
    action_target_progress = getattr(
        snapshot, "phase_handoff_action_target_progress_successful_draw_count", None
    ) or getattr(snapshot, "target_progress_successful_draw_count", None)
    action_target_remaining = getattr(
        snapshot,
        "phase_handoff_action_target_remaining_successful_draw_count",
        None,
    ) or getattr(snapshot, "target_remaining_successful_draw_count", None)
    request = snapshot.request
    follow_on_action = _appendix_g_request_materialization_follow_on_action(request)
    public_next_step_status = _appendix_g_public_next_step_status(
        root,
        snapshot=snapshot,
        request=request,
    )

    return SimpleNamespace(
        phase_dir=phase_dir,
        snapshot=snapshot,
        latest_summary_label=latest_summary_label,
        latest_plan_label=latest_plan_label,
        latest_summary_number=_phase_inventory_number_from_label(latest_summary_label),
        latest_plan_number=_phase_inventory_number_from_label(latest_plan_label),
        current_frontier=getattr(snapshot, "current_frontier", None),
        current_concrete_next_entry=getattr(
            snapshot, "current_concrete_next_entry", None
        ),
        request_artifact_line=getattr(request, "request_artifact_line", None),
        run_mode_spec=getattr(request, "run_mode_spec", None),
        bounded_monitor_floor_timestamp=getattr(
            snapshot, "bounded_monitor_floor_timestamp", None
        ),
        phase_handoff_read_only_confirmation_marker=getattr(
            snapshot, "phase_handoff_read_only_confirmation_marker", None
        ),
        phase_handoff_recommended_action=getattr(
            snapshot, "phase_handoff_recommended_action", None
        ),
        phase_handoff_progress_floor_lag=getattr(
            snapshot, "phase_handoff_progress_floor_lag", None
        ),
        phase_handoff_remaining_draw_lead=getattr(
            snapshot, "phase_handoff_remaining_draw_lead", None
        ),
        action_target_marker=action_target_marker,
        action_target_progress=action_target_progress,
        action_target_remaining=action_target_remaining,
        pending_materialization_cell_count=getattr(
            snapshot.materialization_status,
            "pending_materialization_cell_count",
            0,
        ),
        pending_result_cell_count=getattr(
            snapshot.materialization_status,
            "pending_result_cell_count",
            0,
        ),
        latest_finish_observability_healthy=getattr(
            public_next_step_status,
            "latest_finish_observability_healthy",
            False,
        ),
        same_packet_reclaim_forbidden=getattr(
            public_next_step_status,
            "same_packet_reclaim_forbidden",
            False,
        ),
        public_next_step=getattr(public_next_step_status, "public_next_step", None),
        follow_on_action=follow_on_action,
        paper_anchor_contract=(
            "paper/diddesign_paper.md keeps 2000 Monte Carlo simulations"
        ),
        stata_verification_anchor_contract=(
            "diddesign-stata/verification/paper_replication/simulation/"
            "24_verification.do keeps 120 result rows, 40 efficiency rows, and "
            "canonical Appendix G full-grid export verification"
        ),
        full_verification_expected_result_row_count=120,
        full_verification_expected_efficiency_row_count=40,
    )


