        phase_handoff_recommended_action=phase_handoff_recommended_action,
        phase_handoff_progress_floor_lag=phase_handoff_progress_floor_lag,
        phase_handoff_remaining_draw_lead=phase_handoff_remaining_draw_lead,
        phase_handoff_live_request_drifted=phase_handoff_live_request_drifted,
        phase_handoff_progress_floor_is_conservative=phase_handoff_progress_floor_is_conservative,
        phase_handoff_second_bounded_monitor_forbidden=phase_handoff_second_bounded_monitor_forbidden,
