def appendix_g_full_lane_executor_full_target_batch_execution_status(
    project_root: str | Path,
    *,
    batch_size: int = 2,
    random_seed: int,
) -> AppendixGFullLaneExecutorFullTargetBatchExecutionStatus:
    root = Path(project_root)
    batch_queue_status = appendix_g_full_lane_executor_full_target_batches_status(
        root,
        batch_size=batch_size,
        random_seed=random_seed,
    )

    # This seam is intentionally honest: it exposes the deterministic queue as the
    # next executable frontier, but it does not pretend any paper-scale batch has run.
    pending_batches = batch_queue_status.batches
    first_pending_batch_index = (
        pending_batches[0].batch_index if pending_batches else None
    )
    remaining_design_cell_count = sum(
        batch.planned_cell_count for batch in pending_batches
    )
    remaining_result_cell_count = sum(
        batch.planned_result_cell_count for batch in pending_batches
    )
    remaining_executor_draw_count = sum(
        batch.required_executor_draw_count for batch in pending_batches
    )
    remaining_bootstrap_draw_count = sum(
        batch.required_bootstrap_draw_count for batch in pending_batches
    )

    return AppendixGFullLaneExecutorFullTargetBatchExecutionStatus(
        current_frontier="appendix_g_full_lane_executor_full_target_batch_execution",
        next_rung=(
            f"execute_appendix_g_executor_full_target_batch_{first_pending_batch_index}"
            if first_pending_batch_index is not None
            else "audit_appendix_g_executor_full_target_batches"
        ),
        requested_n_sim=batch_queue_status.requested_n_sim,
        requested_n_boot=batch_queue_status.requested_n_boot,
        reduced_target_n_sim=batch_queue_status.reduced_target_n_sim,
        reduced_target_n_boot=batch_queue_status.reduced_target_n_boot,
        target_design_cell_count=batch_queue_status.target_design_cell_count,
        target_result_cell_count=batch_queue_status.target_result_cell_count,
        prerequisite_frontier=batch_queue_status.current_frontier,
        prerequisite_completed=batch_queue_status.prerequisite_completed,
        batch_size=batch_queue_status.batch_size,
        batch_count=batch_queue_status.batch_count,
        executed_batch_count=0,
        pending_batch_count=len(pending_batches),
        first_pending_batch_index=first_pending_batch_index,
        pending_batches=pending_batches,
        remaining_design_cell_count=remaining_design_cell_count,
        remaining_result_cell_count=remaining_result_cell_count,
        remaining_executor_draw_count=remaining_executor_draw_count,
        remaining_bootstrap_draw_count=remaining_bootstrap_draw_count,
        paper_tau_value=batch_queue_status.paper_tau_value,
        reduced_truth_effect_values=batch_queue_status.reduced_truth_effect_values,
        reduced_truth_effect=batch_queue_status.reduced_truth_effect,
        requires_truth_scale_bridge=batch_queue_status.requires_truth_scale_bridge,
        reduced_truth_scale_gap=batch_queue_status.reduced_truth_scale_gap,
        reduced_consistency_is_qualitative_only=(
            batch_queue_status.reduced_consistency_is_qualitative_only
        ),
    )


def appendix_g_full_lane_executor_full_target_execution_plan_status(
    project_root: str | Path,
    *,
    batch_size: int = 2,
    random_seed: int,
) -> AppendixGFullLaneExecutorFullTargetExecutionPlanStatus:
    root = Path(project_root)
    batch_status = appendix_g_full_lane_executor_full_target_batches_status(
        root,
        batch_size=batch_size,
        random_seed=random_seed,
    )

    cumulative_result_cell_count = 0
    cumulative_executor_draw_count = 0
    cumulative_bootstrap_draw_count = 0
    execution_batches: list[AppendixGExecutorPlannedExecutionBatchStatus] = []
    for batch in batch_status.batches:
        executor_draw_start = cumulative_executor_draw_count + 1
        cumulative_executor_draw_count += batch.required_executor_draw_count
        executor_draw_stop = cumulative_executor_draw_count
        bootstrap_draw_start = cumulative_bootstrap_draw_count + 1
        cumulative_bootstrap_draw_count += batch.required_bootstrap_draw_count
        bootstrap_draw_stop = cumulative_bootstrap_draw_count
        cumulative_result_cell_count += batch.planned_result_cell_count
        execution_batches.append(
            AppendixGExecutorPlannedExecutionBatchStatus(
                batch_index=batch.batch_index,
                random_seed=batch.random_seed,
                planned_cell_count=batch.planned_cell_count,
                planned_result_cell_count=batch.planned_result_cell_count,
                cumulative_result_cell_count=cumulative_result_cell_count,
                executor_draw_start=executor_draw_start,
                executor_draw_stop=executor_draw_stop,
                bootstrap_draw_start=bootstrap_draw_start,
                bootstrap_draw_stop=bootstrap_draw_stop,
                first_cell=batch.first_cell,
                last_cell=batch.last_cell,
            )
        )

    return AppendixGFullLaneExecutorFullTargetExecutionPlanStatus(
        current_frontier="appendix_g_full_lane_executor_full_target_execution_plan",
        next_rung="execute_appendix_g_executor_full_target_batches",
        requested_n_sim=batch_status.requested_n_sim,
        requested_n_boot=batch_status.requested_n_boot,
        reduced_target_n_sim=batch_status.reduced_target_n_sim,
        reduced_target_n_boot=batch_status.reduced_target_n_boot,
        target_design_cell_count=batch_status.target_design_cell_count,
        target_result_cell_count=batch_status.target_result_cell_count,
        prerequisite_frontier=batch_status.current_frontier,
        prerequisite_completed=batch_status.prerequisite_completed,
        batch_count=batch_status.batch_count,
        batches=tuple(execution_batches),
        required_executor_draw_count=batch_status.required_executor_draw_count,
        required_bootstrap_draw_count=batch_status.required_bootstrap_draw_count,
        paper_tau_value=batch_status.paper_tau_value,
        reduced_truth_effect_values=batch_status.reduced_truth_effect_values,
        reduced_truth_effect=batch_status.reduced_truth_effect,
        requires_truth_scale_bridge=batch_status.requires_truth_scale_bridge,
        reduced_truth_scale_gap=batch_status.reduced_truth_scale_gap,
        reduced_consistency_is_qualitative_only=(
            batch_status.reduced_consistency_is_qualitative_only
        ),
    )


def _appendix_g_full_lane_executor_full_target_batch_status(
    project_root: str | Path,
    *,
    batch_index: int,
    batch_size: int = 2,
    random_seed: int,
) -> AppendixGFullLaneExecutorFullTargetBatchStatus:
    root = Path(project_root)
    if batch_index <= 0:
        raise ValueError(
            "batch_index must be positive for Appendix G full-target batch seams."
        )

    batch_execution_status = (
        appendix_g_full_lane_executor_full_target_batch_execution_status(
            root,
            batch_size=batch_size,
            random_seed=random_seed,
        )
    )
    execution_plan_status = (
        appendix_g_full_lane_executor_full_target_execution_plan_status(
            root,
            batch_size=batch_size,
            random_seed=random_seed,
        )
    )

    if batch_index > len(execution_plan_status.batches):
        raise ValueError(
            "Appendix G full-target batch seam cannot exceed the planned execution batch count."
        )

    if batch_index == 1 and batch_execution_status.first_pending_batch_index != 1:
        raise ValueError(
            "Appendix G full-target batch-1 seam requires batch 1 to remain the first pending batch."
        )

    current_batch = execution_plan_status.batches[batch_index - 1]
    remaining_batches = execution_plan_status.batches[batch_index:]
    next_rung = (
        f"execute_appendix_g_executor_full_target_batch_{remaining_batches[0].batch_index}"
        if remaining_batches
        else "audit_appendix_g_executor_full_target_batches"
    )
    prerequisite_frontier = (
        batch_execution_status.current_frontier
        if batch_index == 1
        else f"appendix_g_full_lane_executor_full_target_batch_{batch_index - 1}"
    )
    prerequisite_completed = (
        batch_execution_status.prerequisite_completed if batch_index == 1 else True
    )

    return AppendixGFullLaneExecutorFullTargetBatchStatus(
        current_frontier=f"appendix_g_full_lane_executor_full_target_batch_{batch_index}",
        next_rung=next_rung,
        requested_n_sim=execution_plan_status.requested_n_sim,
        requested_n_boot=execution_plan_status.requested_n_boot,
        reduced_target_n_sim=execution_plan_status.reduced_target_n_sim,
        reduced_target_n_boot=execution_plan_status.reduced_target_n_boot,
        target_design_cell_count=execution_plan_status.target_design_cell_count,
        target_result_cell_count=execution_plan_status.target_result_cell_count,
        prerequisite_frontier=prerequisite_frontier,
        prerequisite_completed=prerequisite_completed,
        batch_index=current_batch.batch_index,
        batch_count=execution_plan_status.batch_count,
        random_seed=current_batch.random_seed,
        planned_cell_count=current_batch.planned_cell_count,
        planned_result_cell_count=current_batch.planned_result_cell_count,
        executor_draw_start=current_batch.executor_draw_start,
        executor_draw_stop=current_batch.executor_draw_stop,
        bootstrap_draw_start=current_batch.bootstrap_draw_start,
        bootstrap_draw_stop=current_batch.bootstrap_draw_stop,
        first_cell=current_batch.first_cell,
        last_cell=current_batch.last_cell,
        remaining_batch_count_after_current=len(remaining_batches),
        remaining_design_cell_count_after_current=sum(
            batch.planned_cell_count for batch in remaining_batches
        ),
        remaining_result_cell_count_after_current=sum(
            batch.planned_result_cell_count for batch in remaining_batches
        ),
        remaining_executor_draw_count_after_current=sum(
            batch.executor_draw_stop - batch.executor_draw_start + 1
            for batch in remaining_batches
        ),
        remaining_bootstrap_draw_count_after_current=sum(
            batch.bootstrap_draw_stop - batch.bootstrap_draw_start + 1
            for batch in remaining_batches
        ),
        paper_tau_value=execution_plan_status.paper_tau_value,
        reduced_truth_effect_values=execution_plan_status.reduced_truth_effect_values,
        reduced_truth_effect=execution_plan_status.reduced_truth_effect,
        requires_truth_scale_bridge=execution_plan_status.requires_truth_scale_bridge,
        reduced_truth_scale_gap=execution_plan_status.reduced_truth_scale_gap,
        reduced_consistency_is_qualitative_only=(
            execution_plan_status.reduced_consistency_is_qualitative_only
        ),
    )


